JXC({"4501":[["يحيى بن معين","قال إسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ضعيف.",3919],["يحيى بن معين","وَقَال أَبُو حاتم : صدوق.",3919]],"4502":[["يحيى بن معين","قال عَبَّاس الدُّورِيُّ ، عَنْ يحيى بن مَعِين: ابن نمر الذي يروي عَنِ الزُّهْرِيّ ضعيف .",3920],["أبو حاتم الرازي","وَقَال أَبُو حاتم : ليس بقوي لا أعلم روى عنه غير الوليد بْن مسلم وسُلَيْمان بْن كثير، وسفيان بْن حسين أحب إلي منه.",3920]],"4505":[["أحمد بن حنبل","قال عَبد اللَّهِ بْن أحمد بْن حنبل ، عَن أبيه: ليس بشيءٍ.",3921],["يحيى بن معين","وَقَال عَلِيّ بْن الحسن الهسنجاني : سمعت يحيى بن مَعِين يقول: بالكوفة كذأَبَان: أبو نعيم النخعي، وأبو نعيم ضرار بْن صرد.",3921],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : لا بأس بِهِ يكتب حديثه.",3921],["أبو دواد السجستاني","وَقَال أَبُو دَاوُدَ، والنَّسَائي: ضعيف.",3921],["أحمد بن شعيب النسائي","وَقَال أَبُو دَاوُدَ، والنَّسَائي: ضعيف.",3921]],"4506":[["علي بن المديني","وَقَال مُحَمَّد بْن أحمد بْن مُحَمَّد بْن أَبي بَكْر المقدمي، عَن أبيه: سئل علي ابن المديني وأنا حاضر عَنْ أعلى أصحاب أَبِي هُرَيْرة، فبدأ بسَعِيد بْن المُسَيَّب، ثم قال: وبعده أَبُو سلمة بْن عَبْد الرحمن وأبو صالح السمان وابن سيرين. قيل لعلي ابن المديني: فالأعرج؟ فقال: هو ثقة، وهو دون هؤلاء.",3922],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد الله العجلي : مدني، تابعي، ثقة.",3922],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وابن خراش: ثقة.",3922]],"4508":[["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3924]],"4509":[["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : ثقة.",3923]],"4512":[["يحيى بن معين","قال إسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3928]],"4514":[["أبو بكر بن أبي داود","وَقَال أَبُو بَكْر بْن أَبي داود: قدم، يعني: الكوفة - فارا مع القدرية وقد أَبُو أسامة من ابن المبارك عَنِ ابن جابر، وجميعا يحدثان عَنْ مكحول، وابن جابر أيضا دمشقي، فلما قدم هذا، قال: أنا عبد الرَّحْمَن بْن يَزِيد الدمشقي، وحدث عَنْ مكحول فظن أَبُو أسامة أنه ابن جابر الذي روى عنه ابن المبارك، وابن جابر ثقة مأمون يجمع حديثه، وابن تميم ضعيف روى عن الزُّهْرِيّ أحاديث مناكير، حَدَّثَنَا ببعضها مُحَمَّد بْن يحيى النيسابوري فِي علل حديث الزُّهْرِيّ، وَقَال: أحرج على من حدث عني هذه الأحاديث مفردة.",3930],["أحمد بن حنبل","وقَال البُخارِيُّ : قال أَحْمَد بْن حنبل: أخبرت عَنْ مروان، عَن الوليد أنه، قال: لا ترو عنه فإنه كذاب.",3930],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَن يحيى بْن مَعِين: ضعيف فِي الزُّهْرِيّ وغيره.",3930],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وأبو حاتم : ضعيف الحديث.",3930],["أبو حاتم الرازي","وَقَال أَبُو زُرْعَة ، وأبو حاتم : ضعيف الحديث.",3930],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : منكر الحديث.",3930],["أبو دواد السجستاني","وَقَال أَبُو داود : متروك الحديث، حدث عنه أَبُو أسامة وغلط فِي اسمه.",3930],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : متروك الحديث.",3930]],"4515":[["يحيى بن معين","وَقَال إسحاق بن منصور وأبو داود ، عَنْ يَحْيَى بْن معين: ثقة .",3931],["أبو بكر بن أبي داود","وَقَال ابْنه أبو بكر بْن أَبي داود: ثقة مأمون.",3931]],"4516":[["عبد الرحمن بن أبي الزناد","قال عَبْد الرَّحْمَنِ بْن أَبي الزناد ، عَن أبيه، عن الأعرج: ما رأيت رجلا بعد الصحابة أراه أفضل منه.",3932],["محمد بن سعد كاتب الواقدي","وَقَال محمد بن سعد : كان قديما، وولي القضاء لعُمَر بن عبد العزيز، ومات بالمدينة سنة ثلاث وتسعين في خلافة الوليد بْن عَبْد الملك، وكان ثقة قليل الحديث .",3932]],"4517":[["يحيى بن معين","قال إسحاق بن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3933]],"4521":[["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بِهِ بأس. وذكره ابنُ حِبَّان فِي كتاب \"الثقات\" . وقد ذكرنا قول علي بن المديني فيه في ترجمة عبد الرحمن بن هرمز الأعرج . روى له البخاري في كتاب\"القراءة خلف الإمام\"والباقون.",3936]],"4523":[["أبو حاتم الرازي","قال أبو حاتم : صدوق.",3938],["الخطيب البغدادي","قال الحافظ أبو بكر الخطيب : وأحسب أن هذا هو الذي كنى عنه محمد بن عَبد الرحيم في قوله: وشيئا آخر. وذكره ابنُ حِبَّان فِي كتاب \"الثقات\" ، وَقَال: كان صاعقة لا يحمد أمره.",3938],["الدارقطني","وَقَال الدَّارَقُطنِيّ : لا بأس به.",3938],["يحيى بن معين","قال عباس الدروي ، عَنْ يحيى بْن مَعِين: ليس بشيءٍ .",3938],["إبراهيم بن يعقوب الجوزجاني","وَقَال إبراهيم بن يعقوب الجوزجاني : غير ثقة.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : واهي، ضعيف الحديث.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : ترك حديثه، منكر الحديث، كان يفسد أباه يحدث عنه بالطامات.",3938],["أبو دواد السجستاني","وَقَال أَبُو داود : ضعيف .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : متروك الحديث.",3938],["أبو دواد السجستاني","وَقَال أَبُو بَكْر بْن أَبي خيثمة عَن يحيى بْن مَعِين، وأبو داود : ثقة .",3938],["أبو زرعة الرازي","قال أبو زُرْعَة : شيخ فاضل ثقة.",3938],["يحيى بن معين","قال أبو بكر بْن أَبي خيثمة ، عَن يَحْيَى بْن مَعِين: ضعيف الْحَدِيث.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : يكتب حديثه ولا يحتج به.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: أرجو إنه لا بأس بِهِ.",3938],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ : متروك الحديث يكذب.",3938],["أبو حاتم الرازي","قال أبو حاتم : كان فاضلا متعبدا صدوقا يعد من الأبدال .",3938],["يحيى بن معين","قال عباس الدروي ، عَنْ يحيى بْن مَعِين: ليس بشيءٍ.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : منكر الحديث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بثقة .",3938],["أحمد بن حنبل","وَقَال أَبُو زُرْعَة الدمشقي، عَن أَبِي الحسن بن سميع، عن أحمد بن صالح المِصْرِي: قلت لأحمد بن حنبل: رأيت أحدا أحسن حديثا من عبد الرزاق؟ قال: لا. قال أبو زُرْعَة: عبد الرزاق أحد من ثبت حديثه.",3938],["عبد الرزاق بن همام","وَقَال محمد بن أَبي السري العسقلاني، عَنْ عَبْدِ الوهاب بن همام أخي عبد الرزاق: كنت عند معمر وكان خاليا، فقال: يختلف إلينا في طلب العلم من أهل اليمن أربعة: رباح بن زيد، ومحمد بن ثور، وهشام بن يوسف، وعبد الرزاق بن همام، فأما رباح فخليق أن تغلب عليه العبادة فينتفع بنفسه ولا ينتفع به الناس، وأما هشام فخليق أن يغلب عليه السلطان، وأما ابن ثور فكثير النسيان، قليل الحفظ، وأما ابن همام فإن عاش فخليق أن تضرب إليه أكباد الإبل.",3938],["أحمد بن حنبل","وَقَال حنبل بْن إِسْحَاقَ، عَنْ أَحْمَد بْن حنبل نحو ذَلِكَ، وزاد: من سمع من الكتب فهو أصح.",3938],["أحمد بن حنبل","وَقَال أبو زُرْعَة الدمشقي : قلت لأحمد بن حنبل: كان عبد الرزاق يحفظ حديث معمر؟ قال: نعم، قيل له: فمن أثبت في ابن جُرَيْج عبد الرزاق أو محمد بن بكر البرساني؟ قال: عبد الرزاق.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: كَانَ عبد الرزاق في حديث معمر أثبت من هشام بن يوسف، وكان هشام بن يوسف في حديث ابن جُرَيْج أثبت من عبد الرزاق، وكان أقرأ للكتب، وكان أعلم بحديث سفيان الثوري من عبد الرزاق.",3938],["علي بن المديني","وَقَال يعقوب بْن شَيْبَة، عَن علي بْن المديني، قال لي هشام بن يوسف: كان عبد الرزاق أعلمنا وأحفظنا.",3938],["يحيى بن معين","وَقَال أَبُو مُحَمَّد عَبد اللَّهِ بْن أَحْمَد بْن ربيعة بْن زبر، عن جعفر بْن مُحَمَّدِ بْنِ أَبي عثمان الطيالسي: سمعت يحيى بن مَعِين يقول: سمعت من عَبْد الرزاق كلاما يوما فاستدللت بِهِ على ما ذكر عنه من المذهب، فقلت له: إن أستاذيك الذين أخذت عنهم ثقات، كلهم أصحاب سنة: معمر، ومالك بْن أنس، وابن جُرَيْج، وسفيان الثوري، والأَوزاعِيّ، فعمن أخذت هذا المذهب؟ فَقَالَ: قدم علينا جعفر بْن سُلَيْمان الضبعي، فرأيته فاضلا حسن الهدي، فأخذت هذا عنه.",3938],["عبد الله بن أحمد بن حنبل","وَقَال عَبد اللَّهِ بْن أَحْمَد بْن حنبل : سَأَلتُ أبي، قلت: عبد الرزاق كان يتشيع ويفرط في التشيع؟ فقال: أما أنا فلم أسمع منه في هذا شيئا، ولكن كان رجلا تعجبه أخبار الناس، أو الأخبار.",3938],["الخطيب البغدادي","قال الحافظ أبو بكر الخطيب : حدث عنه المعتمر بن سُلَيْمان التَّيْمِيّ، وإسحاق بن إبراهيم الدبري وبين وفايتهما ثمان وتسعون سنة. وحدث عنه ابن عُيَيْنَة وبين وفاته ووفاة الدبري سبع وثمانون سنة . روى له الجماعة. أَخْبَرَنَا أَحْمَدُ بْن أَبي الخير، قال: أَنْبَأَنَا خليل بْن أَبي الرجاء الراراني ومَسْعُودُ بْنُ أَبي مَنْصُورٍ الْجَمَّالُ، قالا: أَخْبَرَنَا أَبُو علي الحداد، قال: أَخْبَرَنَا أَبُو نُعَيْمٍ الْحَافِظُ، قال: أخبرنا سُلَيْمان بْنُ أَحْمَدَ، قال: حَدَّثَنَا إسحاق بْن.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : ضعيف .",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : شيخ متروك الحديث .",3938],["أحمد بن حنبل","وَقَال أبو بكر الأثرم . عَن أحمد بن حنبل: لاأعلمه إلا ثقة.",3938],["يحيى بن معين","وَقَال معاوية بن صَالِح، عَنْ يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : يكتب حديثه.",3938],["يحيى بن معين","وَقَال عثمان بن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: صدوق .",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : ثقة صدوق.",3938],["أبو عيسى الترمذي","وَقَال التِّرْمِذِيّ : ثقة حافظ.",3938],["يحيى بن معين","قال عَبَّاس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: عبد السلام مولى قريش ثقة مديني.",3938],["يحيى بن معين","وَقَال عُمَر بن الحسن بْن عَلِيّ بْن مالك ، عَن أَبِيهِ: سألت يحيى بن مَعِين عَن أبي الصلت الهروي، فقال: ثقة صدوق إلا أنه يتشيع.",3938],["زكريا بن يحيى الساجي","وَقَال زكريا بن حيى الساجي : يحدث بمناكير، هو عندهم ضعيف.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ليس بثقة.",3938],["أبو بكر البرقاني","وَقَال أبو بكر البرقاني :، عَن أبي الحسن الدارقطني، كان رافضا حبيثا، قال لي دعلج: إنه سمع أبا سعد الهروي الزاهد وقيل له، ما تقول في عبد السام بن صالح؟ فقال: نعيم بن الهيصم ثقة.",3938],["أحمد بن حنبل","قال أبو حاتم : شيخ . ٣٤٢٣ - مق د: عبد السلام بن عبد الرحمن بن صخر بن عبد الرحمن بن وابصة بن معبد الأسدي الوابصي ، أبو الفضل الرَّقِّيّ، قاضي الرقة وحران وحب، ثم ولي القضاء ببغداد في أيام المتوكل. رَوَى عَن: عَبد الله بن جعفر الرَّقِّيّ (مق)، وأبيه عبد الرحمن بن صخر الأسدي (د)، وجد أبيه عبد الرحمن بن وابصة ولم يدركه، ووكيع بْن الجراح.",3938],["أبو حاتم الرازي","قال أبو حاتم : هو وأبوه ضعيفان.",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : صدوق.",3938],["أبو حاتم الرازي","قال أَبُو حاتم : صدوق.",3938],["أبو دواد السجستاني","قال أبو داود، عن عاصم بْن عُمَر بْن علي المقدمي: مات في رجب سنة أربع وعشرين ومئتين . ٣٤٢٧ - عس: عبد السلام الكوفي. . قال إِسْمَاعِيلُ بْنُ أَبي خَالِدٍ (عس)، عَنْ عَبْدِ السَّلامِ: رَجُلٌ مِنْ حَيِّهِ: خَلا عَلَيٌّ بِالزُّبَيْرِ يَوْمَ الْجَمَلِ، فَقَالَ: أَنْشُدُكَ اللَّهَ، كَيْفَ سمعت رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ويقول: لَتُقَاتِلُنَّهُ بِبَنِي فُلانٍ وأَنْتَ ظَالِمٌ لَهُ، ثُمَّ لَيُنْصَرَنَّ عَلَيْكَ\".",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : لين الحديث ضعفه أحمد.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : لين الحديث ضعفه أحمد بن حنبل، يكتب حديثه، ليس بالمتروك .",3938],["محمد بن إسماعيل البخاري","قال البخاري ، وأبو حاتم : منكر الحديث .",3938],["أبو حاتم الرازي","قال البخاري ، وأبو حاتم : منكر الحديث .",3938],["أحمد بن شعيب النسائي","قال النَّسَائي : لا بأس به.",3938],["عبد الله بن أحمد بن حنبل","وَقَال أَبُو بَكْر بْن أَبي دَاوُدَ ، عَنْ عَبد اللَّهِ بْنِ أحمد بْن حنبل: سئل أبي عن حديث: \"تبني مدينة\"قال: ما حدث به إنسان ثقة.",3938],["يحيى بن معين","وَقَال إبراهيم بن عَبد اللَّهِ بْنِ الجنيد : سمعت يَحْيَى بن مَعِين سئل عن عبد العزيز بن أبان، فقال: كذاب خبيث يضع الحديث.",3938],["علي بن الحسين بن حبان","وَقَال علي بْن الحسين بْن حبان : وجدت فِي كتاب أَبِي بخط يده: سألت أبا زكريا عن الواقدي، قال: كان كذابا.",3938],["يعقوب بن شيبة","وَقَال يعقوب بن شَيْبَة : وعبد العزيز بن أبان عند أصحابنا جميعًا متروك، كثير الخطأ، كثير الغلط، وقد ذكروه بأكثر من هذا، وسمعت محمد بن عَبد الله بن نمير يقول: ما رأيت أحدا أبين أمرا منه، وَقَال: هو كذاب.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : متروك الحديث، لا يشتغل به، تركوه لا يكتب حديثه .",3938],["أحمد بن شعيب النسائي","وقال النَّسَائي : متروك الحديث.",3938],["محمد بن إسماعيل البخاري","قال الْبُخَارِيّ : لا يتابع فِي حَدِيثِهِ. وذَكَرَهُ ابنُ حِبَّان فِي كتاب \"الثقات\"، وَقَال : روى عن عائشة ولم يسمع منها .",3938],["أحمد بن حنبل","قال أبو طالب : سئل أَحْمَد بْن حَنْبَلٍ عن عبد العزيز بْن أَبي حازم، فقال: لم يكن يعرف بطلب الحديث إلا كتب أبيه فإنهم يقولون: إنه سمعها. وكان يتفقه لم يكن بالمدينة بعد مالك أفقه منه، ويُقال: إن كتب سُلَيْمان بن بلال وقعت إليه ولم يسمعها.",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : صدوق.",3938],["يعقوب بن شيبة","وَقَال يعقوب بْن شَيْبَة: ثقة صدوق.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: أخبرنا عَمْرو بن علي، قال: حَدَّثَنِي عبد العزيز بن الخطاب، ثقة.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة .",3938],["أحمد بن حنبل","وَقَال عَبد اللَّهِ بْن أحمد بْن حنبل عَن أبيه، وإسحاق بْن منصور ، عَن يحيى بْن مَعِين، وأبو حاتم ، والنَّسَائي: ثقة.",3938],["يحيى بن سعيد القطان","قال أحمد بْن مُحَمَّد بْن يحيى بْن سَعِيد القطان ، عَنْ جَدِّهِ: عبد العزيز بن أَبي رواد ثقة في الحديث ليس ينبغي أن يترك حَدِيثه لرأي أخطأ فِيهِ.",3938],["أحمد بن حنبل","وَقَال عَبد اللَّهِ بْن أَحْمَد بْنِ حَنْبَلٍ ، عَن أَبِيهِ: رجل صالح الحديث، وكان مرجئا وليس هو في التثبت مثل غيره.",3938],["يحيى بن معين","وَقَال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة .",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صدوق، ثقة في الحديث، متعبد.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : لا بأس بن هو من كبار الشيعة.",3938],["محمد بن سعد كاتب الواقدي","قال محمد بن سعد : كان يقال له: العبد. رَوَى عَن: أنس بن مالك (ع)، وشهر بن حوشب، وعبد الواحد البناني، وكنانة بن نعيم العدوي، ومحمد بن زياد الجمحي، وأبي صفية صاحب أبي رزين، وأبي غالب صاحب أمامة، وأبي نضرة العبدي (م ت س ق) .",3938],["شعبة بن الحجاج","قال يحيى بْن سَعِيد القطان، عن شعبة: عبد العزيز بن صهيب في أنس أحب إلي من قتادة، أو قال: أثبت من قتادة.",3938],["عبد الله بن أحمد بن حنبل","وَقَال عَبد الله بْن أحمد بْن حنبل : سَأَلتُ أبي عن عبد العزيز بن صهيب، فقال: ثقة ثقة، عبد الوارث أروى الناس عنه.",3938],["يحيى بن معين","وَقَال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة .",3938],["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3938],["علي بن الحسين بن حبان","وَقَال علي بْن الحسين بْن حبان : وجدت فِي كتاب أَبِي بخط يده، قيل لأبي زكريا: عبد العزيز الماجشون هو مثل ليث وإبراهيم بن سعد؟ فقال: لا، هو دونهما، إنما كان رجلا يقول بالقدر والكلام ثم تركه وأقبل إلى السنة، ولم يكن من شأنه الحديث، فلما قدم بغداد كتبوا عنه، فكان بعد يقول: جعلني أهل بغداد محدثا، وكان صدوقا ثقة .",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة ، وأبو حاتم ، وأَبُو دَاوُد، والنَّسَائي: ثقة.",3938],["أبو حاتم الرازي","وَقَال أبو زُرْعَة ، وأبو حاتم ، وأَبُو دَاوُد، والنَّسَائي: ثقة.",3938],["أبو دواد السجستاني","وَقَال أبو زُرْعَة ، وأبو حاتم ، وأَبُو دَاوُد، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال أبو زُرْعَة ، وأبو حاتم ، وأَبُو دَاوُد، والنَّسَائي: ثقة.",3938],["أحمد بن سنان القطان","وَقَال أَحْمَد بْن سنان القطان : سَمِعْتُ عَبْدُ الرَّحْمَنِ بْنُ مَهِدِيٍّ قال: قال بشر بن السري، لم يسمع ابن أَبي ذئب ولا الماجشون من الزُّهْرِيّ.",3938],["عبد الرحمن بن مهدي","وَقَال أَحْمَد بْن سنان القطان : سَمِعْتُ عَبْدُ الرَّحْمَنِ بْنُ مَهِدِيٍّ قال: قال بشر بن السري، لم يسمع ابن أَبي ذئب ولا الماجشون من الزُّهْرِيّ.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كَانَ ثقة كثير الحديث، وأهل العراق أروى عنه من أهل المدينة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["أبو حاتم الرازي","قال أَبُو حاتم : منكر الحديث، روى عن يحيى البكاء، عَنِ ابْنِ عُمَر ثلاثة أحاديث أو أربعة منكرة .",3938],["أحمد بن حنبل","قال أبو بكر الأثرم ، عَن أَحْمَد بْن حَنْبَل: كَانَ ثقة.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو داود ، والنَّسَائي: ثقة.",3938],["أبو دواد السجستاني","وَقَال أَبُو زُرْعَة ، وأَبُو داود ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال أَبُو زُرْعَة ، وأَبُو داود ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال أبو بكر بن السني، عن النَّسَائي: عن بشر بن معاذ، عن إبراهيم بن عبد العزيز، قال، حَدَّثني أبي عبد العزيز، قال: حَدَّثَنِي جدي عَبد المَلِك، عن أبي محذورة. وهو وهم، والصواب الأول، والله أعلم.",3938],["أبو بكر الأثرم","قال أبو بكر الأثرم: سمعت أبا عَبد اللَّهِ يسأل عن عبد العزيز بْن عُبَيد اللَّه الذي روى عنه إسماعيل بن عياش، فقال: كنت أظن أنه مجهول حتى سألت عنه بحمص، فإذا هو عندهم معروف، ولا أعلم أحدا روى عنه غير إسماعيل، وَقَالوا: هو من ولد صهيب.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ضعيف لم يحدث عنه إلا إسماعيل بن عياش.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : يروي عن أهل الكوفة وأهل المدينة، ولم يرو عنه أحد غير إسماعيل بن عياش وهو عندي عجيب، ضعيف، منكر الحديث، يكتب حديثه، يروي أحاديث مناكير، ويروي أحاديث حسانا.",3938],["أبو دواد السجستاني","وَقَال أَبُو داود : ليس بشيءٍ.",3938],["يعقوب بن سفيان","وَقَال يعقوب بن سفيان : حَدَّثَنَا أَبُو نعيم، قال: حَدَّثَنَا عبد العزيز بن عُمَربن عبد العزيز وهو ثقة.",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة : لا بأس به.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : يكتب حديثه.",3938],["إسحاق بن سيار النصيبي","وَقَال إسحاق بْن سيار النصيبي: سمعت أبا مسهر وزعم أن عبد العزيز بن عُمَربن عبد العزيز ضعيف، وكل شيء من أمره.",3938],["أبو زرعة الدمشقي","وَقَال أَبُو زُرْعَة الدمشقي ، عَن أَبِي نعيم: قدم علينا عبد العزيز بن عُمَربن عبد العزيز، وجعفر بن برقان الكوفة سنة أربع وأربعين ومئة، وفي نسخة: سنة سبع وأربعين ومئة.",3938],["الزبير بن بكار","وَقَال الزبير بن بكار: ولي المدينة ومكة ليزيد بن الوليد بن عَبد المَلِك ثم أثبته مروان بن محمد عليهما: ثم عزله عنهما، وله يقول ابن مافنة يرثيه: قد كبا الدهر بجدي فعثر • إذ ثوى عبد العزيز بن عُمَر كان من عبد مناف كليهما • بمكان السمع منها والبصر .",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: ليس بثقة، إنما كان صاحب شعر.",3938],["محمد بن يحيى النيسابوري","وَقَال أَحْمَد بْن الحسن بن الفضل السكوني : سمعت محمد بن يحيى النيسابوري يقول: علي بدنة إن حدثت عن عبد العزيز بن عِمْران حديثا. ورأيته يضعفه جدا.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : منكر الحديث، لا يكتب حديثه.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : متروك الحديث.",3938],["يحيى بن معين","قال إسحاق بن مَنْصُور ، عَنْ يحيى بْن مَعِين: عبد العزيز بن قريرثقة .",3938],["أبو حاتم الرازي","قال أَبُو حاتم : مجهول. وذكره ابنُ حِبَّان في كتاب \"الثقات\" . روى له البخاري في كتاب\"القراءة خلف الإمام\"وفي\"الأدب.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَن يحيى بن مَعِين: الدَّراوَرْدِيّ أثبت من فليح بن سُلَيْمان، وابن أَبي الزناد، وأبي أويس الدَّراوَرْدِيّ، ثم ابن أَبي حازم.",3938],["يحيى بن معين","وَقَال أحمد بْن سعد بْن أَبي مريم، عَن يحيى بْن مَعِين: ثقة حجة .",3938],["محمد بن سعد كاتب الواقدي","وَقَال محمد بن سعد : ولد بالمدينة ونشأ بها، وسمع بها العلم والأحاديث ولم يزل بها حتى توفي سنة سبع وثمانين ومئة، وكان ثقة كثير الحديث يغلط .",3938],["يحيى بن معين","قال إسحاق بن منصور ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة : لا بأس به.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صالح الحديث، مستوى الحديث، ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["محمد بن أبي سعيد","وَقَال محمد بن هانئ الطائي، عَنْ مُحَمَّدِ بْنِ أَبي سَعِيد: قال عبد العزيز بن مروان: ما نظر إلي رجل قط فتأملني فأشتد تأمله أياي إلا سألته عن حاجته، ثم أثبت من ورائها فإذا تعار من وسنه مستطيلا لليله مستبطئا لصبحه متأرقا للقائي، ثم غدا إلي أنا تجارته في نفسه، وغدا التجار إلى تجاراتهم إلا رجع من غدوه إلي فأربح من تجر، وعجبا لمؤمن موقن يوقن أن الله يرزقه ويوقن أن الله يخلف عليه كيف يدخر مالًا عن عظم أجر أو حسن سماع.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة .",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صالح الحديث، ثقة.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : صدوق لا بأس به، هو أفضل من عَبد الله بن عاصم .",3938],["أبو حاتم الرازي","قال أبو حاتم : صدوق.",3938],["أبو حاتم الرازي","قال أبو حاتم : كتبت عنه بسلمية، وهو صدوق، ثقة، مأمون.",3938],["أبو جعفر العقيلي","وَقَال أَبُو جَعْفَرٍ العقيلي : يحدث عن الثقات بالبواطيل، ويدعي من الحديث مالا يعرف به غيره من المتقدمين، عن مالك وغيره. ذكر الحاكم أبو عبد الله أن أبا عَمْرو المستملي سمع منه في شعبان سنة ثلاثين ومئتين .",3938],["أبو حاتم الرازي","قال أَبُو حاتم : لا بأس به، صدوق.",3938],["الخطيب البغدادي","وَقَال أَبُو بَكْر الخطيب: ولد بأفريقية سنة أربعين ومئة، وخرج به أبوه، وهو طفل إلى البصرة، وكانت أمه من أهلها، فنشأ بها، وتفقه، وسمع الحديث بها، ثم رجع إلى مصر مع أبيه، فسمع من الليث، وغيره، وسمع بالشام، والجزيرة، واستوطن مصر، وحدث بها، وكان يكره أن يقال له الحراني، وإنما سمي بذلك لأن أخويه عَبد الله، وعبد العزيز ولدا بها، ولم يزالا بها، وكان لهما بها ثروة، ونعمة، ومات أبو صالح بمصر سنة أربع وعشرين ومئتين، فيما قاله البخاري ، وغيره، ويُقال: سنة خمس وعشرين.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي: لا بأس به .",3938],["أبو حاتم الرازي","قال أبو حاتم : لا بأس به.",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : كَانَ صدوقا .",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي ، والدارقطني : ثقة.",3938],["الدارقطني","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي ، والدارقطني : ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة .",3938],["أبو بكر الأثرم","قال أبو بكر الأثرم ، عَن أحمد بن جنبل: ثقة.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: لا بأس به، هو صدوق .",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : لا بأس به، صالح الحديث.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كَانَ ثقة، وتوفي بالبصرة سنة أربع ومئتين في خلافة عَبد اللَّهِ بن هارون.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","قال أبو حاتم : مجهول، ويُقال: إنه متروك الحديث.",3938],["أحمد بن حنبل","قال أبو طالب ، عَن أحمد بن حنبل: ثقة، ثبت، وهو أثبت من خصيف في الحديث، وهو صاحب سنة، وليس هو فوق سالم، يعني: الافطس -.",3938],["يحيى بن معين","وَقَال معاوية بْن صالح، عَن يحيى بن مَعِين: ثقة، ثبت .",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كَانَ ثقة كثير الحديث، وهو مولى محمد ابن مروان بن الحكم.",3938],["أحمد بن صالح الجيلي","وَقَال محمد بْن عَبد الله بْن عمار، وأحمد بْن عَبد الله العجلي ، وأَبُو زُرْعَة ، وأَبُو حَاتِم ، والنَّسَائي وغير واحد: ثقة.",3938],["أبو زرعة الرازي","وَقَال محمد بْن عَبد الله بْن عمار، وأحمد بْن عَبد الله العجلي ، وأَبُو زُرْعَة ، وأَبُو حَاتِم ، والنَّسَائي وغير واحد: ثقة.",3938],["أبو حاتم الرازي","وَقَال محمد بْن عَبد الله بْن عمار، وأحمد بْن عَبد الله العجلي ، وأَبُو زُرْعَة ، وأَبُو حَاتِم ، والنَّسَائي وغير واحد: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال محمد بْن عَبد الله بْن عمار، وأحمد بْن عَبد الله العجلي ، وأَبُو زُرْعَة ، وأَبُو حَاتِم ، والنَّسَائي وغير واحد: ثقة.",3938],["أبو زرعة الدمشقي","وَقَال أبو زُرْعَة الدمشقي: ثقة، أخذ عنه الأكابر: مسعر، وسفيان، وأهل طبقتهم، وقد قال سفيان: ما رأيت عربيا أثبت من عبد الكريم.",3938],["يعقوب بن شيبة","وَقَال يَعْقُوب بْن شَيْبَة: إلى الضعف ما هو، وهو صدوق، ثقة وقد روى مالك عنه، وكان ممن ينتقي الرجال.",3938],["الحميدي","وَقَال الحميدي عن سفيان: كان حافظا، وكان من الثقات، لا يقول إلا سمعت وحَدَّثَنَا ورأيت .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: أخبرنا إبراهيم بن يعقوب، عن آخر، قال: قلت لعلي: عبد الكريم الجزري إلى من تضمه؟ قال: ذاك ثبت ثبت.",3938],["عبيد الله بن عمرو الرقي","وَقَال عُبَيد اللَّه بْن عَمْرو الرَّقِّيّ: قال لي سفيان بن سَعِيد: يا أبا وهب لقد جاءنا صاحبكم عبد الكريم الجزري بأحاديث لو حَدَّثَنَا بها هؤلاء الكوفيون ما زالوا يفخرون بها علينا، منها: النوم توبة.",3938],["أحمد بن حنبل","قال عَبد اللَّهِ بْن أَحْمَد بْن حنبل، عَن أبيه، عن عَبْدِ الرَّزَّاقِ: قال معمر: سألني حماد عن فقهائنا، فذكرتهم، فقال: قد تركت أفقههم، يعني: عبد الكريم أبا أمية.",3938],["عبد الله بن أحمد بن حنبل","وَقَال عَبد اللَّهِ بْن أَحْمَد بْنِ حنبل في موضع آخر: سَأَلتُ أبي عن عبد الكريم أبي أمية، فقال: بصري نزل مكة، وكان معلما، وهو ابن أَبي المخارق، وكان ابن عُيَيْنَة يستضعفه. قلت له: هو ضعيف؟ قال: نعم .",3938],["معمر بن راشد","وَقَال عَباس الدُّورِيُّ ، عَن يحيي ابن مَعِين: حَدَّثَنَا هشام بن يُوسُفَ، عن معمر، قال: قال أيوب: لا تأخذوا عن عبد الكريم أبي أمية، فإنه ليس بثقة.",3938],["خالد الحذاء","وَقَال إسماعيل ابن علية، عن خالد الحذاء: كان عبد الكريم إذا سافر يقول أبو العالية: اللهم لا ترد علينا صاحب الأكسية.",3938],["مالك بن أنس","وَقَال الحميدي، عن سفيان : قلت لأيوب: يا أبا بكر، مالك لم تكثر عن طاوس؟ قال: أتيته لأسمع منه فرأيته بين ثقيلين: عبد الكريم أبي أمية، وليث بن أَبي سليم، فذهبت وتركته",3938],["سفيان بن عيينة","وَقَال التِّرْمِذِيّ في حديث سفيان بن عُيَيْنَة عن عَبْدِ الْكَرِيمِ أَبِي أُمَيَّةَ، عن حَسَّانِ بْنِ بِلالٍ، عن عمار، في تخليل اللحية، قال أَحْمَد: قال ابْن عُيَيْنَة: لم يسمع عَبْد الكريم من حسان بْن بلال حديث التخليل.",3938],["يحيى بن معين","قال عبد الخالق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : شيخ ثقة، كتبنا عنه ببغداد.",3938],["يحيى بن معين","وَقَال إسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["يحيى بن معين","وَقَال أحمد بْن سعد بْن أَبي مريم، عَن يحيى بْن مَعِين: ثقة، يوري ستة أحاديث أو نحوها.",3938],["أحمد بن حنبل","قال عبد الوهاب بن أَبي عصمة، عن أَحْمَد بْن أَبي يحيى، سمعت أَحْمَد بْن حنبل يقول: عَبد المجيد بن أَبي رواد ثقة ، وكان فيه غلو في الإرجاء، وكان يقول: هؤلاء الشكاك.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ وعبد اللَّهِ بْن أَحْمَد بْن حنبل وأحمد بْن سعد بْن أَبي مريم ، عَن يحيى بْن مَعِين: ثقة .",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : ليس بالقوي، يكتب حديثه .",3938],["الدارقطني","وَقَال الدَّارَقُطنِيّ : لا يحتج به، يعتبر به، وأبوه أيضا لين، والابن أثبت، قيل: إنه مرجئ، ولا يعتبر بأبيه، يترك، وهما مكيان.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة.",3938],["أبو زرعة الرازي","قال أبو زُرْعَة : لا بأس به.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ليس بشيءٍ .",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : هو من عتق الشيعة، محله الصدق، صالح الحديث، يكتب حديثه .",3938],["علي بن المديني","قال علي بن المديني: سمعت جريرا ذكر عن مغيرة، قال: عَبد المَلِك الأَعور أثبت من حماد فيما روى عن إبراهيم.",3938],["يحيى بن سعيد القطان","وَقَال علي بْن المديني ، عَن يحيى بن سَعِيد القطان: كان ثقة.",3938],["أحمد بن حنبل","وَقَال عَبد اللَّهِ بْن أَحْمَد بْن حنبل ، عَن أَبِيهِ: ثقة.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كَانَ سخيا سريا، وقد روى عنه، مات فِي أول خلافة هِشَام بْن عَبد المَلِك، وكان ثقة، وله أحاديث.",3938],["حاتم بن الليث الجوهري","وَقَال حاتم بْن الليث الجوهري ، عن سريج بن النعمان: قدم علينا بغداد فأقام بها، وكتبنا عنه،\"المغازي\"عن عمه عَبد الله بن أَبي بكر، وكان هارون ولاه القضاء ببغداد عسكر المهدي ، وكان عَبد المَلِك يكنى أبا طاهر، ومات ببغداد في زمن هارون سنة سبع وسبعين ومئة، وحضرت جنازته.",3938],["أبو زرعة الرازي","قال أبو زُرْعَة : مدني ثقة .",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة.",3938],["أحمد بن حنبل","قال أبو طالب ، عَن أحمد بْن حنبل: لا بأس به.",3938],["يحيى بن معين","وَقَال إسحاق بْن منصور، عَن يحيى بْن مَعِين: ثقة.",3938],["أحمد بن حنبل","قال عَبد اللَّهِ بْن أَحْمَد بْنِ حنبل ، عَن أَبِيهِ: يحيى بْن عبد الملك ثقة هو وأبوه متقاربان في الحديث.",3938],["يحيى بن معين","وَقَال إسحاق بْن منصور ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["أبو حاتم الرازي","قال أبو حاتم : لا بأس بِهِ.",3938],["عبد الله بن أحمد بن حنبل","وَقَال عَبد اللَّهِ بْن أحمد بْن حنبل : سَأَلتُ أبي عن ابن أبجر، فقال: بخ ثقة.",3938],["يحيى بن معين","وَقَال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة.",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة ، وأبو حاتم : ابن أبجر أحب إلينا من إسرائيل.",3938],["أبو حاتم الرازي","وَقَال أبو زُرْعَة ، وأبو حاتم : ابن أبجر أحب إلينا من إسرائيل.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: هذا حديث منكر.",3938],["علي بن الحسين بن حبان","وَقَال علي بْن الحسين بْن حبان : وجدت في كتاب أبي بخط يده: سئل أبو زكريا يحيى بن مَعِين عن حديث عطاء، عن جَابِرٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ في الشفعة . قال: هو حديث لم يحدث به أحد إلا عَبد المَلِك بن أَبي سُلَيْمان، عن عطاء، وقد أنكره عليه الناس، ولكن عَبد المَلِك ثقة صدوق لايرد على مثله: قلت له: تكلم شعبة فيه؟ قال: نعم، قال شعبة: لو جاء عَبد المَلِك بآخر مثل هذا لرميت بحديثه.",3938],["أحمد بن حنبل","وَقَال عَبد الله بْن أَحْمَد بْن حنبل ، عَن أَبِيهِ: هذا حديث منكر.",3938],["الخطيب البغدادي","قال الحافظ أبو بكر الخطيب : قد أساء شعبة في اختياره حيث حدث عَنْ مُحَمَّدِ بْنِ عُبَيد الله العرزمي وترك التحديث عن عَبد المَلِك بْن أَبي سُلَيْمان، لأن محمد بن عُبَيد الله لم يختلف الأئمة من أهل الأثر في ذهاب حديثه وسقوط روايته، وأما عَبد المَلِك فثناؤهم عليه مستفيض وحسن ذكرهم له مشهور.",3938],["أبو زرعة الدمشقي","وَقَال أبو زُرْعَة الدمشقي : سمعت أحمد ويحيى يقولان: كان عبد الملك بن أَبي سُلَيْمان ثقة.",3938],["يحيى بن معين","وَقَال إسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ضعيف، وهو أثبت في عطاء من قيس بن سعد.",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي : ثقة ثبت في الحديث، ويُقال: كان سفيان الثوري يسميه الميزان، وكان راوية عن عطاء بن أَبي رباح.",3938],["يعقوب بن سفيان","وَقَال يعقوب بْن سفيان : حَدَّثَنَا أَبُو نُعَيْمٍ، قال: حَدَّثَنَا سفيان عن عبد الملك بن أَبي سُلَيْمان، العرزمي ثقة متقن فقيه.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة الرازي : لا بأس بِهِ.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي : ثقة .",3938],["أبو زرعة الرازي","قال أبو زُرْعَة : منكر الحديث.",3938],["عمرو بن علي الفلاس","وَقَال عَمْرو بن علي : حَدَّثَنَا أبو العباس عَبد المَلِك بن عبد الرحمن الذماري وكان ثقة.",3938],["يحيى بن سعيد القطان","وَقَال علي بن المديني : سألت يحيى بن سَعِيد: من أثبت أصحاب نافع؟ قال: أَيُّوب، وعُبَيد الله، ومالك بن أنس، وابن جُرَيْج أثبت من مالك في نافع.",3938],["أحمد بن حنبل","وَقَال صالح بْن أحمد بْن حنبل، عَن أبيه: عَمْرو بْنِ دِينَارٍ وابْنِ جُرَيْج أثبت الناس في عطاء.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: لَيْسَ بشيءٍ فِي الزُّهْرِيّ .",3938],["يحيى بن معين","وَقَال أَحْمَد بْن سعد بْن أَبي مريم ، عَن يحيى بن مَعِين: ثقة في كل ماروى عنه من الكتاب .",3938],["يحيى بن سعيد القطان","وَقَال جعفر بن عبد الواحد، عَن يحيى بْن سَعِيد: كان ابن جُرَيْج صدوقا فإذا قال: حَدَّثَنِي\"فهو سماع، وإذا قال: أخبرنا\"أو\"أخبرني\"فهو قراءة، وإذا قال: قال\"فهو شبه الريح .",3938],["عبد الرزاق بن همام","وَقَال أحمد بن حنبل ، عَنْ عَبْدِ الرَّزَّاقِ: ما رأيت أحدا أحسن صلاة من ابن جُرَيْج.",3938],["أبو حاتم الرازي","قال أَبُو حاتم ، وأَبُو دَاوُد ، والنَّسَائي : ثقة.",3938],["أبو دواد السجستاني","قال أَبُو حاتم ، وأَبُو دَاوُد ، والنَّسَائي : ثقة.",3938],["أحمد بن شعيب النسائي","قال أَبُو حاتم ، وأَبُو دَاوُد ، والنَّسَائي : ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : أَبُو نصر التمار من أبناء خراسان من أهل نسا، ذكر أنه ولد بعد قتل أبي مسلم الداعية بستة أشهر ونزل بغداد في ربض أبي العباس الطوسي في درب النَّسَائية وتجر بها في التمر وغيره، وكان ثقة فاضلا خيرا ورعا، وتوفي ببغداد يوم الثلاثاء أول يوم من المحرم سنة ثمان وعشرين ومئتين ودفن بباب حرب وهو يومئذ ابن إحدى وتسعين سنة، وكان بصره قد ذهب.",3938],["يحيى بن معين","وَقَال عثمان بن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : صدوق.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة مأمون.",3938],["أبو موسى المديني","قال الحافظ أبو موسى المديني الأصبهاني: وهذا لايمنع أن يكون بطنا من قيس وقد ينسب إليهم بشر بن معاذ العقدي.",3938],["إسحاق بن راهويه","وَقَال عَبد الله بْن مُحَمَّد بْن جَعْفَر القزويني، عَن أبي زكريا الأعرج النيسابوري: كان إسحاق بن راهويه إذا حَدَّثَنَا عَن أبي عامر العقدي، قال: حَدَّثَنَا أبو عامر الثقة الأمين.",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي : يقول له: ابن القبطية، كان على قضاء الكوفة، وهو صالح الحديث، روى أكثر من مئة حديث، وَقَال أبو حاتم : ليس بحافظ، وهو صالح الحديث، تغير حفظه قبل موته.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : ضعيف الحديث، ليس بالقوي، يحدث بالمناكير عن الثقات.",3938],["يحيى بن معين","قال عَبَّاس الدُّورِيُّ ، عَنْ يحيى بن مَعِين: سمعت الأَصْمَعِيّ يقول: سمع مني مالك بن أنس.",3938],["يحيى بن معين","وَقَال أَبُو بَكْر بْن أَبي خيثمة ، عَن يحيى بْن مَعِين: الأَصْمَعِيّ ثقة.",3938],["يحيى بن معين","وَقَال أَبُو معين الحسين بْن الحسن الرازي : سألت يحيى بْن مَعِين عن الأَصْمَعِيّ فقال: لم يكن ممن يكذب، وكان من أعلم الناس في فنه.",3938],["الخطيب البغدادي","قال الْحَافِظ أَبُو بَكْر الْخَطِيب : كان من أهل البصرة فانتقل عنها، وسكن بغداد وحدث بها إلى حين وفاته، وكان مذكورا بالصلاح والخير، وكان سمج الوجه.",3938],["الدارقطني","وَقَال الدَّارَقُطنِيّ : صدوق كثير الخطأ من الأسانيد والمتون، كان يحدث من حفظه فكثرت الأَوهام منه.",3938],["محمد بن جرير الطبري","وَقَال أبو جَعْفَر مُحَمَّد بْن جرير الطبري: ما رأيت أحفظ من أبي قلابة.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم الرازي : سألت دحيما عَنْ عَبد المَلِك بْنِ مُحَمَّدٍ الصنعاني فكأنه ضجع. فقلت: هو أثبت أو عقبة بن علقمة؟ فقال: ما أقربهما.",3938],["يحيى بن معين","قال أَبُو بَكْر بْن أَبي خيثمة ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["يحيى بن معين","قال إسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : لا بأس به.",3938],["محمد بن سعد كاتب الواقدي","قال مُحَمَّد بْن سعد : توفي في خلافه عُمَربن عبد العزيز، وكان قليل الحديث . روى لَهُ البخاري فِي كتاب\"القراءة خلف الإمام\"حديثا، وابن ماجه آخر.",3938],["أبو حاتم الرازي","زاد أَبُو حاتم: صدوق.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بن مَعِين: قرة العجلي عن عَبد المَلِك ابن أخي القعقاع ضعيف لا شئ.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : شيخ مجهول لم يرو إلا حديثا واحدا، قطع الشيباني ذلك الحديث حديثين، لا يكتب حديثه، منكر الحديث .",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : ضعيف الْحَدِيث.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : فيه نظر.",3938],["أبو دواد السجستاني","قال أبو داود، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","قال أبو داود، والنَّسَائي: ثقة.",3938],["محمد بن إسماعيل البخاري","قال الْبُخَارِيّ ، وأَبُو حَاتِم : منكر الحديث.",3938],["أبو حاتم الرازي","قال الْبُخَارِيّ ، وأَبُو حَاتِم : منكر الحديث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بثقة.",3938],["محمد بن إسماعيل البخاري","قال البخاري : منكر الحديث .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بثقة .",3938],["محمد بن إسماعيل البخاري","قال أبو حاتم : لا بأس به.",3938],["أحمد بن حنبل","قال علي بن الْحَسَن الهسنجاني، عن أَحْمَد بْن حنبل، عن عفان: أحفظ عن شيخ ثقة: عبد المؤمن السدوسي.",3938],["يحيى بن معين","وَقَال أَبُو بكر بْن أَبي خيثمة، عَن يحيى بْن مَعِين: ثقة .",3938],["يحيى بن معين","قال عباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["يحيى بن معين","قال عثمان بْن سَعِيد الدارمي ، عَنْ يحيى بْن مَعِين: ليس به بأس. وذكره أَبُو حاتم محمد بن حبان في كتاب \"الثقات\" . روى له مسلم، والتِّرْمِذِيّ، والنَّسَائي، حديثا واحدا، وقد وقع لنا عاليا عنه. أَخْبَرَنَا بِهِ أَحْمَد بْن أَبي الخير، قال: أَنْبَأَنَا أَبُو الْحَسَنِ الجمال، قال: أَخْبَرَنَا أَبُو عَلِيّ الحداد، قال: أَخْبَرَنَا أبو نعيم الحافظ، قال: حَدَّثَنَا أَبُو عَمْرو بْنُ حَمْدَانَ، قال: حَدَّثَنَا عَبد اللَّهِ بْن مُحَمَّد بْنِ شِيرَوَيْهِ، قال: حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ.",3938],["يحيى بن معين","قال معاوية بن صالح : قلت ليحيى بْن مَعِين: من أثبت أصحاب الأعمش؟ قال: بعد سفيان، وشعبة: أبو معاوية الضرير، وبعده عبد الواحد بن زياد.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي : قلت ليحيى بن مَعِين: أبو عوانة أحب إليك، أو عبد الواحد بن زياد؟ قال: أبو عوانة أحب إلي وعبد الواحد ثقة .",3938],["يحيى بن سعيد القطان","وَقَال صَالِح بْن أَحْمَد بْن حنبل، عن علي بْن المديني: سمعت يَحْيَى بْن سَعِيد يقول: ما رأيت عبد الواحد بن زياد يطلب حديثا قط بالبصرة، ولا بالكوفة، وكنا نجلس على بابه يوم الجمعة بعد الصلاة أذاكره حديث الأعمش فلا يعرف منه حرفا.",3938],["محمد بن سعد كاتب الواقدي","وَقَال محمد بن سعد : كان يعرف بالثقفي، وهو مولى لعبد القيس، وكان ثقة كثير الْحَدِيث.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وأبو حاتم : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو زُرْعَة ، وأبو حاتم : ثقة.",3938],["أحمد بن حنبل","قال عَبد اللَّهِ بْن أَحْمَد بْن حَنْبَلٍ، عَن أَبِيهِ: حديثه حديث منكر، أحاديثه موضوعة.",3938],["يحيى بن معين","وَقَال معاوية بْن صَالِح ، عَنْ يحيى بْن مَعِين: ضعيف.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ليس بثقة.",3938],["يحيى بن معين","قال عَبَّاس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ليس بشيءٍ .",3938],["أحمد بن صالح الجيلي","وَقَال أحمد بْن عَبد اللَّهِ العجلي : شامي تابعي ثقة.",3938],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ : ثقة من أهل حمص ولي إمارة المدينة، محمود الإمارة.",3938],["يحيى بن معين","قال إسحاق بن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["أبو زرعة الرازي","قال أبو زُرْعَة : صدوق.",3938],["يحيى بن معين","وَقَال عثمان بن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: ثقة.",3938],["أحمد بن صالح الجيلي","وَقَال أحمد بْن عَبد اللَّهِ العجلي : شامي، تابعي، ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ضعيف.",3938],["الحاكم","وَقَال الحاكم أبو أحمد: منكر الحديث.",3938],["يحيى بن معين","وَقَال عبد الخالق بْن مَنْصُور، عَنْ يحيى بْن مَعِين: ثقة .",3938],["علي بن الحسين بن حبان","وَقَال علي بْن الحسين بْن حبان: وجدت فِي كتاب أبي بخط يده: ذكر أبو زكريا أبا عُبَيدة الحداد فقال: كان من المتثبتين ما أعلم أنا أخذنا عليه خطأ البتة، جيد القراءة لكتابه.",3938],["أحمد بن صالح الجيلي","وَقَال أحمد بْن عَبد الله العجلي ، ويعقوب بن شَيْبَة ، ويعقوب بْن سفيان ، وأَبُو دَاوُدَ : ثقة.",3938],["أبو دواد السجستاني","وَقَال أحمد بْن عَبد الله العجلي ، ويعقوب بن شَيْبَة ، ويعقوب بْن سفيان ، وأَبُو دَاوُدَ : ثقة.",3938],["شعبة بن الحجاج","قال عَبْد الرحمن بْن المبارك ، عن معاذ بن معاذ: سألت أنا ويحيى بن سَعِيد شعبة عن شيء من حديث أبي التياح، فقال: ما يمنعكم من ذاك الشاب، يعني: عبد الوارث - فما رأيت أحدا أحفظ لحديث أبي التياح منه، فقمنا فجلسنا إليه، فسألناه فجعل يمرها كأنها مكتوبة في قلبه.",3938],["أبو جعفر المسندي","وَقَال أَبُو جَعْفَرٍ المسندي، قال لي خلف: قال لي عبد الصمد بن عبد الوارث أنه كان عند شعبة فلما قال، يعني: أباه، قال شعبة: تعرف الإتقان في قفاه.",3938],["عبيد الله بن عمر القواريري","وَقَال عُبَيد الله بن عُمَر القواريري: كان يحيى بْن سَعِيد لا يحدث عن أحد ممن أدركنا مثل حماد، وأصحابه، إلا عن عبد الوارث فإنه كان يثبته، فإذا خالفه أحد من أصحابه، قال: ما قال عبد الوارث .",3938],["يحيى بن معين","وَقَال معاوية بْن صالح : قلت ليحيى بْن مَعِين: من أثبت شيوخ البَصْرِيّين؟ قال: عبد الوارث بن سَعِيد، مع جماعة سماهم.",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : ثقة صدوق، ممن يعد مع ابن علية، وبشر بن المفضل ووهيب، يعد من الثقات، هو أثبت من حماد بن سلمة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة ثبت.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بن سعد : كان ثقد حجة، توفي بالبصرة في المحرم سنة ثمانين ومئة .",3938],["أبو حاتم الرازي","قال أبو حاتم : صدوق.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : لا بأس به.",3938],["يحيى بن معين","قال عباس الدُّورِيُّ ، عن يَحْيَى بْن مَعِين: قد سمع مالك بن أنس من عبد الوهاب بن بخت، وكان ثقة، وكان شاميا نزل المدينة قال: وسلمة بن بخت: حدث عنه يوسف السمتي، وإسحاق الرازي، وكان سلمة أيضا ثقة وليس بينه وبين عبد الوهاب قرابة.",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة الرازي ، ويعقوب بن سفيان ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال أبو زُرْعَة الرازي ، ويعقوب بن سفيان ، والنَّسَائي: ثقة.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : صالح الحديث لا بأس به.",3938],["محمد بن جرير الطبري","وَقَال محمد بن جرير الطبري : ذكر محمد بن عُمَر، عَنْ عَبْدِ العزيز ابن عُمَر أن عبد الوهاب بن بخت غزا مع البطال فانكشفوا فجعل عبد الوهاب يكر فرسه وهو يقول: ما رأيت فرسا أجبن منك، سفك الله دمي إن لم أسفك دمك، ثم ألقى بيضته عن رأسه وصاح: أنا عبد الوهاب بن بخت أمن الجنة تفرون؟ !",3938],["أبو حاتم الرازي","قال أبو حاتم : ثقة، صحيح الحديث، ما به بأس، من قدماء أصحاب الزُّهْرِيّ.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة .",3938],["أحمد بن شعيب النسائي","وَقَال أبو النَّسَائي: ليس بثقة متروك .",3938],["أبو جعفر العقيلي","وَقَال أَبُو جَعْفَرٍ العقيلي ، وأَبُو الْحَسَنِ الدَّارَقُطنِيّ ، وأبو بكر البيهقي: متروك .",3938],["الدارقطني","وَقَال أَبُو جَعْفَرٍ العقيلي ، وأَبُو الْحَسَنِ الدَّارَقُطنِيّ ، وأبو بكر البيهقي: متروك .",3938],["أبو بكر البيهقي","وَقَال أَبُو جَعْفَرٍ العقيلي ، وأَبُو الْحَسَنِ الدَّارَقُطنِيّ ، وأبو بكر البيهقي: متروك .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي ، والدَّارَقُطنِيّ : ثقة.",3938],["الدارقطني","وَقَال النَّسَائي ، والدَّارَقُطنِيّ : ثقة.",3938],["الخطيب البغدادي","وَقَال أَبُو بَكْر الْخَطِيب : كَانَ ثقة صالحا ورعا زاهدا.",3938],["عبد الله بن أحمد بن حنبل","وَقَال أبو علي الصواف ، عن عَبد اللَّهِ بن أَحْمَد بْن حنبل: سمعت أَبِي يقول: عبد الوهاب الثقفي أثبت من عبد الاعلى الشامي، الثقفي أعرف وأوثق عند أصحابه من عبد الاعلى.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي : سألت يحيى بْن مَعِين، قلت: فالثقفي؟ قال: ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كان ثقة وفيه ضعف، وتوفي سنة أربع وتسعين ومئة فِي خلافة مُحَمَّد بن هارون .",3938],["يحيى بن معين","وَقَال ابن الغلابي ، عن يَحْيَى بْن مَعِين: يكتب حديثه.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَن يحيى بن مَعِين: ثقة.",3938],["أحمد بن حنبل","وَقَال عَبد اللَّهِ بْن أَحْمَد بْن حَنْبَلٍ ، عَن أَبِيهِ: قال وكيع: كانوا يقولون إن عبد الوهاب بن مجاهد لم يسمع من أبيه.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ضعيف .",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : ضعيف الحديث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بثقة، ولا يكتب حديثه .",3938],["يعقوب بن شيبة السدوسي","وَقَال يعقوب بن شَيْبَة السدوسي: ثقة.",3938],["أبو حاتم الرازي","قال أبو حاتم : اراه مرسل .",3938],["صالح بن أحمد بن حنبل","قال صالح بْن أحمد بْن حنبل: سَأَلتُ أبي عنه؟ فَقَالَ: ثقة ثقة، وزيادة مع صلاح في بدنه، وكان شديد الفقر",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي: سألت يحيى بْن مَعِين، قلت: أَبُو أسامة أحب إليك أو عبدة بن سُلَيْمان؟ فقال: مامنهما إلا ثقة .",3938],["أحمد بن صالح الجيلي","وَقَال أحمد بن عَبد الله العجلي : ثقة رجل صالح صاحب قرآن يقرئ.",3938],["محمد بن سعد كاتب الواقدي","وَقَال محمد بْن سعد : كان ثقة، مات بالكوفة لثلاث خلون من رجب سنة ثمان وثمانين ومئة في خلافة هارون وصلى عليه محمد بْن ربيعة الكِلابي .",3938],["أبو حاتم الرازي","قال أبو حاتم : صدوق.",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : صدوق.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة.",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : صدوق.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة.",3938],["يعقوب بن سفيان","وَقَال يعقوب بْن سُفْيَان ، وأَبُو حاتم ، والنَّسَائي، وابن خراش: ثقة.",3938],["أبو حاتم الرازي","وَقَال يعقوب بْن سُفْيَان ، وأَبُو حاتم ، والنَّسَائي، وابن خراش: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال يعقوب بْن سُفْيَان ، وأَبُو حاتم ، والنَّسَائي، وابن خراش: ثقة.",3938],["عبدة بن أبي لبابة","وَقَال ابن ثوبان، عن عبدة بن أَبي لبابة: كنت في سبعين من أصحاب ابن مسعود، وقرأت عليهم القرآن ما رأيت منهم اثنين يختلفان يحمدون الله على الخير، ويستغفرونه من الذنوب.",3938],["العباس الدوري","قال عباس الدُّورِيُّ ، عَنْ يحيي: ثقة، وكَانَ عريف قومه.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ فِي \"التاريخ\": عُبَيد اللَّه بْن بسر، عَن أَبِي أمامة قاله ابن المبارك، عَنْ صفوان بْن عَمْرو الشامي .",3938],["أبو القاسم الطبراني","وَقَال أَبُو الْقَاسِمِ الطَّبَرَانِي فِي ترجمة أَبِي أمامة من\"المعجم الكبير\": عَبد اللَّهِ بْن بسر اليحصبي، عَن أَبِي أمامة، ثُمَّ روى له هَذَا الحَدِيث من رواية نعيم بْن حماد عَنِ ابْنِ المبارك عن ابْن المبارك، وحَدِيثا آخر من رواية بقية بْن الْوَلِيد، عَنْ صفوان بْن عَمْرو: حببوا اللَّه إِلَى عباده يحببكم اللَّه\"، وقَدْ قيل: إنه عَبد اللَّهِ بْن بسر الحبراني، وقَدْ تقدم فِي ترجمة الحبراني أَنَّهُ يروى عَن أَبِي أمامة، ويروي عَنْهُ صفوان بْن عَمْرو.",3938],["أحمد بن حنبل","قال عَبد اللَّهِ بْن أَحْمَد بْن حنبل ، عَن أبيه، وإسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين، وأبو داود ، والنَّسَائي: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : ثقة بابة يزيد بْن أَبي حبيب، روى عن المتقدمين والمتأخرين.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : ثقة بقية زمانه.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: فقيه بصري ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سَعْد : ولي قضاء البصرة بَعْد سوار بن عَبد اللَّهِ، وكان ثقة، محمود عاقلا من الرجال.",3938],["محمد بن المثنى","وَقَال أَبُو موسى مُحَمَّد بْن المثنى: ما سمعت عَبْد الرحمن بْن مهدي يُحَدِّثُ عَنْ عُبَيد اللَّهِ بْنِ أَبي حميد الهذلي، ضعيف الحَدِيث، وهُوَ كوفي.",3938],["يحيى بن معين","وَقَال عَبد الله بْن أَحْمَدَ الدورقي عن يَحْيَى بْن مَعِين، وعُثْمَان بْن سَعِيد الدارمي عَنْ دحيم: ضعيف الحَدِيث .",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : منكر الحديث.",3938],["أبو دواد السجستاني","وَقَال أبو داود: ضعيف.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بثقة.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : منكر الحديث، ضعيف الحديث.",3938],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ : ضعيف الحَدِيث .",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم ، وأَبُو بَكْر الخطيب : ثقة.",3938],["الخطيب البغدادي","وَقَال أَبُو حاتم ، وأَبُو بَكْر الخطيب : ثقة.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، وأبو بكر بْن أَبي خيثمة عَن يحيى بْن مَعِين: ليس بشيءٍ.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي ، عَن يَحْيَى بْن مَعِين: كُل حَدِيثه عندي ضعيف .",3938],["علي بن المديني","وَقَال أَبُو الْحَسَن بْن البراء ، عَن علي بْن المديني: منكر الحديث.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : لا بأس به، صدوق.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : لين الحديث.",3938],["الخطيب البغدادي","وَقَال أبو بكر الخطيب: كان رجلا صالحا وفِي حَدِيثه لين .",3938],["يعقوب بن سفيان","وَقَال يعقوب بْن سفيان: سمعت الْحَجَّاج بْن أَبي منيع يَقُول أمام الزُّهْرِيّ بالرصافة: عشرين سنة إلا أربعة أشهر خلافة هِشَام كلها إلا أَن يَكُون حج فاستمكنوا منه.",3938],["ابن شهاب الزهري","وَقَال مُحَمَّد بْن يَحْيَى الذهلي فيمن روى عن الزُّهْرِيّ: ومنهم إِسْحَاق بْن يَحْيَى العوصي وهُوَ مجهول من أَصْحَاب الزُّهْرِيّ لَمْ أعلم له راوية غير يحيى بْن صَالِح الوحاظي من أَهل حمص، وعُبَيد اللَّه بْن أَبي زِيَاد من أَهل الرصافة رصافة الشام لَمْ أعلم لَهُ راوية غَيْر ابْن ابنه يقال لَهُ: الْحَجَّاج بْن أَبي منيع، أخرج إلي جزءا من أحاديث الزُّهْرِيّ فنظرت فيها فوجدتها صحاحا فلم أكتب منها إلا يسيرا.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : لَيْسَ بالقوي ولا المتين، هُوَ صَالِح الحَدِيث، يكتب حَدِيثه، ومحمد بْن عَمْرو بْن علقمة أحب إلي منه يحول من كتاب\"الضعفاء\"الَّذِي صنفه الْبُخَارِي.",3938],["عثمان بن سعيد الدارمي","وَقَال عُثْمَان بْن سَعِيد الدارمي، عَن دحيم: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : لا بأس بِهِ.",3938],["الخطيب البغدادي","وَقَال أَبُو بَكْر الخطيب : كَانَ ثقة.",3938],["أبو القاسم البغوي","قال أَبُو الْقَاسِمِ الْبَغَوِي ، ومحمد بْن مخلد : مات فِي ذي الحجة سنة ستين ومئتين.",3938],["أبو دواد السجستاني","وَقَال أَبُو داود: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة مأمون، قل من كتبنا عَنْهُ مثله.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : لا بأس به.",3938],["يحيى بن معين","قال إِسْحَاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["أبو دواد السجستاني","قال إسحاق بْن منصور عَن يحيى بْن مَعِين، وأَبُو دَاوُدَ : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : لا بأس بِهِ، كَانَ سُلَيْمان بْن حرب يثنى عَلَيْهِ.",3938],["محمد بن سعد كاتب الواقدي","قال مُحَمَّد بْن سعد في الطبقة الخامسة من الصَّحَابَة : عُبَيد اللَّه بْن عَبَّاس وكَانَ أصغر سنا من عَبد اللَّهِ بسنة، وكَانَ رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قبض وهُوَ ابْن اثنتي عشرة سنة، وقَدْ رأى النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وسمع منه، وكان شيخا جوادا.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة .",3938],["أبو زرعة الرازي","قال أَبُو زرعة : ثقة.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : ثقة مأمون إمام.",3938],["ابن شهاب الزهري","وَقَال عَبد اللَّهِ بْن شبيب المدني، عَنْ يَعْقُوب بْن مُحَمَّد الزُّهْرِيّ، عَنْ إِبْرَاهِيم بْن مُحَمَّد بْن عَبْد الْعَزِيزِ الزُّهْرِيّ، عَن أَبِيهِ، عَنِ الزُّهْرِيّ: مَا جالست أحدا من الْعُلَمَاء إلا وأرى أني قَدْ أتيت عَلَى مَا عنده، وقَدْ كنت أختلف إِلَى عروة بْن الزُّبَيْر حَتَّى مَا كنت أسمع منه إلا معادا مَا خلا عُبَيد الله بْن عَبد الله بْن عتبة فَإِنَّهُ لَمْ آته إلا وجدت عنده علما طريفا.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال أَبُو زُرْعَة ، والنَّسَائي: ثقة.",3938],["أحمد بن حنبل","وَقَال أَبُو الْحَسَن الميموني، عن أحمد بن حنبل: حديث بئر بضاعة صحيح وحَدِيث أَبِي هُرَيْرة: لا يبال فِي (الماء؟) الراكد\"أثبت وأصح إسنادا.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ضعيف .",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : شيخ، وحَدِيثه مستقيم . روى له التِّرْمِذِيّ، والنَّسَائي وسمياه: عَبد اللَّهِ ، وسماه النَّسَائي فِي\"حَدِيث مَالِك\"عُبَيد اللَّه. ٣٦٦٠ - م ت س ق: عُبَيد اللَّه بن عَبْد الكريم بن يَزِيد بن فروخ القرشي المخزومي ، أَبُو زُرْعَة الرازي، مولى عياش بن مطرف بن عَبد اللَّهِ بْن عياش بْن أَبي ربيعة، أحد الأئمة المشهورين، والأعلام المذكورين، والجوالين المكثرين، والحفاظ المتقنين.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : إمام.",3938],["الخطيب البغدادي","وَقَال أبو بكر الخطيب : كان إماما ربانيا حافظا متقنا مكثرا صادقا، قدم بغداد غَيْر مرة وجلس أَحْمَد بْن حنبل وذاكره.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : حَدَّثَنِي أَبُو زرعة ومَا خلف بعده مثله علما وفقها وفهما وصينانة وصدقا، وهَذَا مَا لا يرتاب فِيهِ، ولا أعلم من المشرق والمغرب من كَانَ يفهم هَذَا الشأن مثله، ولقد كَانَ من هَذَا الأمر بسبيل.",3938],["أحمد بن حنبل","وَقَال أَبُو بَكْر البيهقي: حَدَّثَنَا أَبُو عَبْد اللَّهِ الْحَافِظ، قال: سمعت أبا جَعْفَر مُحَمَّد بْن أَحْمَد الرازي يَقُول: سمعت أبا عَبد اللَّهِ مُحَمَّد بْن مسلم بْن وارة يَقُول: كنت عند إِسْحَاق بْن إِبْرَاهِيم بنيسابور، فَقَالَ رجل من أَهل العراق: سمعت أَحْمَد بْن حنبل يَقُول: صح من الحَدِيث سبع مئة ألف حَدِيث وكسر، وهَذَا الفتى يَعْنِي أبا زرعة قَدْ حفظ ست مئة ألف حَدِيث.",3938],["الحاكم","وَقَال الحاكم أَبُو أَحْمَد الحافظ: سمعت أَحْمَد بْن خَالِد الحروري يَقُول: دَخَلَ أَبُو زرعة بغداد متوجها إِلَى الحج فاجتمع إِلَيْهِ الحفاظ يذاكرونه وهُوَ يجيب ويغلبهم فِي المذاكرة حَتَّى عجزوا عَنْ مذاكرته، فقام واحد مِنْهُم، قال فِي أذنه: يا دا نانا ، وشتمه بأقبح شتيمة، فتبسم أَبُو زُرْعَة، وَقَال لَهُ: يا هَذَا اشتغل بالعلم فَإِن هَذَا بعيد مِمَّا نحن فِيهِ.",3938],["يونس بن عبد الأعلى","وَقَال عَبْد الرَّحْمَنِ بْن أَبي حَاتِم: سمعت يونس بن عبد الاعلى يقول: ما رأيت أكثر تواضع من أَبِي زرعة هُوَ وأَبُو حاتم إماما خراسان.",3938],["محمد بن عمر الرازي","وَقَال أبو بكر مُحَمَّد بْن عُمَر الرازي الْحَافِظ: لَمْ يكن فِي هذه الأمة أحفظ من أَبِي زرعة الرازي، كان يحفظ سبع مئة الف حديث، وكالن يحفظ مئة وأربعين ألفا فِي التفسير والقراءات، قال: وحفظ كتب أَبِي حَنِيفَة فِي أربعين يوما فكان يسردها مثل الماء. قال: وكَانَ لا يعرف سنجة عشرين من سنجة خمسة .",3938],["يحيى بن معين","وَقَال أحمد بْن مُحَمَّد بْن القاسم بْن محرز ، عَن يحيى بْن مَعِين: مَا كَانَ بالكوفة أحد أعلم بسفيان من الأشجعي، كَانَ أعلم بِهِ من عَبْد الرحمن بْن مهدي، ومن يَحْيَى بْن سَعِيد، وأبي أحمد الزبيري، وقبيصة، وأبي حذيفة.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: لَيْسَ أحد فِي حَدِيث الثَّوْرِي يشبه هؤلاء: ابن المبارك، ويَحْيَى بْن سَعِيد الْقَطَّان، ووكيع بْن الجراح، وعَبْد الرَّحْمَنِ بْن مهدي، وأَبُو نعيم، فقيل لَهُ: والأشجعي؟ قال: الأشجعي ثقة مأمون ولكن هاتوا من يَرْوِي عَنْهُ، وبعد هَؤُلاءِ فِي سُفْيَان: يَحْيَى بْن آدم، وعُبَيد اللَّه بن موسى، وأبو أحمد الزبيري، وأَبُو حذيفة، وقبيصة، ومعاوية بْن هِشَام القصار، والفريابي، وأَبُو دَاوُد الحفري.",3938],["يحيى بن معين","وَقَال عثان بْن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: صَالِح ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["عثمان بن سعيد الدارمي","وَقَال عثمان بْن سَعِيد الدارمي، عَن دحيم: ثقة.",3938],["أبو زرعة الدمشقي","قال أَبُو زُرْعَة الدمشقي ، عَنْ عَبد المَلِك بْن الأصبغ: قُلْت لمنبه بْن عُثْمَان: لَمْ تسمع من أَبِي وهب صاحب مكحول شَيْئًا؟ قال: ذاك مَاتَ مدخل عَبد اللَّهِ بْن عَلِي دمشق.",3938],["أبو القاسم البغوي","قال أَبُو الْقَاسِمِ الْبَغَوِي: بلغني أَنَّهُ ولد عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وذكره مُحَمَّد بْن سعد في الطبقة الأولى من تابعي أهل الْمَدِينَة ، وَقَال: أمه أم قتال بنت أسيد بْن أَبي العيص بن أمية بن عَبْد شمس بْن عَبْد مناف بْن قصي، ولَهُ دار بالمدينة عِنْدَ دار عَلِي بْن أَبي طَالِب، ومَاتَ بالمديسنة في خلافة الوليد بْن عَبد المَلِك، وكان ثقة قليل الحديث.",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي : مدني تابعي ثقة، من كبار التابعين، وهُوَ ابْن أخت عُثْمَان بْن عَفَّان.",3938],["خليفة بن خياط","قال خليفة بْن خياط : مَاتَ فِي آخر ولاية الوليد بن عبد الملك. ومَاتَ الْوَلِيد بْن عَبد المَلِك سنة ست وتسعين . روى له البخاري، ومسلم، وأبو دَاوُد، والنَّسَائي. أَخْبَرَنَا أَحْمَد بْن أَبي الخير، قال: أَنْبَأَنَا أَبُو الْحَسَنِ الْجَمَّالُ، قال: أَخْبَرَنَا أَبُو عَلِيّ الحداد، قال: أَخْبَرَنَا أَبُو نُعَيْمٍ الْحَافِظُ، قال: حَدَّثَنَا أَبُو بكر أَحْمَد بْنُ يُوسُفَ بْنِ خَلادٍ، قال: حَدَّثَنَا أحمد بْن إِبْرَاهِيم بْن مِلْحَانَ، قال: حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ.",3938],["محمد بن إسماعيل البخاري","قال الْبُخَارِي : لا يثبت حَدِيثه .",3938],["أبو عيسى الترمذي","قال التِّرْمِذِيّ : وعُبَيد اللَّه بْن عَلِي أصح. رَوَى عَن: سَعِيد بْن المُسَيَّب، وجده أَبِي رافع مُرْسلًا، وجدته سلمى أم رافع (د ت ق)، ويُقال: عمته.",3938],["يحيى بن معين","قال أَبُو بكر بْن أَبي خيثمة : سئل يَحْيَى بْن مَعِين عَنِ ابْن أَبي رافع، عَنْ عمته، قال: لا بأس بِهِ.",3938],["عمرو بن علي الفلاس","وَقَال عَمْرو بْن عَلِي : ذكرت ليحيى بْن سَعِيد قَوْل عَبْد الرحمن بْن مهدي أَن مالكا فِي نَافِع أثبت من عُبَيد اللَّه بْن عُمَر، فغضب وَقَال: هُوَ أثبت من عُبَيد اللَّه؟ !",3938],["أحمد بن حنبل","وَقَال أَبُو حاتم : سألت أَحْمَد بْن حَنْبَل عَنْ مَالِك، وعُبَيد اللَّه بْن عُمَر، وأيوب أيهم أثبت فِي نَافِع؟ فَقَالَ: عُبَيد اللَّه أثبتهم وأحفظهم وأكثرهم رواية.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم : ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة ثبت.",3938],["يحيى بن معين","قال عُثْمَان بْن سَعِيد الدارمي ، وأَبُو بَكْرِ بْنُ أَبي خيثمة عَن يحيى بْن مَعِين: ثقة.",3938],["يحيى بن معين","وَقَال مُحَمَّد بْن هَارُون الفلاس : سألت يَحْيَى بْن مَعِين عَنْ مسدد والقواريري، فَقَالَ: مَا مِنْهُم إلا صدوق.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كان ثقة، كثير الحديث.",3938],["عبد المؤمن بن خلف النسفي","وَقَال عبد المؤمن بْن خلف النسفي: سمعت أَبَا علي صالح بْن مُحَمَّد يَقُول: القواريري أثبت من الزهراني وأشهر وأعلم بحَدِيث البصرة، ما رأيت أحدا أعلم بحديث البصرة منه ومن عَلِي ومن ابرايهم بْن عرعرة، وقَدْ سمعت القواريري يَقُول: مَا رأيت أبا الرَّبِيع عِنْدَ حماد بْن زَيْد قط.",3938],["محمد بن سعد كاتب الواقدي","وَقَال الْحُسَيْن بْن فَهُمْ صاحب مُحَمَّد بْن سَعْد: توفي ببغداد يَوْم الجمعة لثلاث عشرة ليلة خلت من ذي الحجة سنة خمس وثلاثين ومئتين ، وحضره خلق كثير ودفن بعسكر الْمَهْدِي خارج الثلاثة الأبواب، وهُوَ يوم توفي ابن أربع وثمانين سنة .",3938],["يحيى بن معين","قال أَبُو بكر بْن أَبي خيثمة ، عَن يحيى بْن مَعِين: ثقة .",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : صَالِح الحَدِيث، ثقة، صدوق، لا أعرف لَهُ حَدِيثا منكرا، هُوَ أحب إلي من زهير بْن مُحَمَّد.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سَعْد : كَانَ ثقة، صدوقا، كثير الحديث وربما أخطأ، وكَانَ أحفظ من روى عن عَبْد الكريم الجزري، ولَمْ يكن أحد ينازعه فِي الفتوى فِي دهره، ومَاتَ بالرقة سنة ثمانين ومئة فِي خلافة هَارُون .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة مأمون.",3938],["يحيى بن معين","قال إسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["أبو زرعة الرازي","قال أَبُو زُرْعَة : ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كان ثقة، قليل الحديث.",3938],["الحاكم","وَقَال الحاكم أَبُو أَحْمَد فِي \"الكنى\": أَبُو الْخَطَّاب عَبْد الرَّحْمَنِ بْن عَبد اللَّهِ بْن كعب بْن مَالِك سمع عمه عُبَيد اللَّه بْن كعب بْن مَالِك، وكَانَ قائد كعب حِينَ أصيب بصره. وكَانَ أعلم قومه وأوعاهم لأحاديث أصحاب رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",3938],["أحمد بن حنبل","قال أبو طالب ، عَن أحمد بْن حنبل: صدوق فِي الحَدِيث.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صدوق ثقة، روى عنه أحمد بْن حنبل وكَانَ عنده عَنْ حماد بْن سلمة تسعة آلاف حَدِيث، وكَانَ عنده رقائق وفصاحة وحسن خلق وسخاء.",3938],["زكريا بن يحيى الساجي","وَقَال زكريا بْن يحيى الساجي : صدوق، قرف بالقدر، وكَانَ بريئا منه سمعت مُحَمَّد بْن عَائِشَة ابْن أخي ابن عَائِشَة يذكر ذَلِكَ، وَقَال: إِنَّمَا كَانَ لَهُ خلق جميل، وكَانَ يتحبب إِلَى النَّاس ويحب المحامد فكان كُل من جاءه لقيه بالبشر، ومَا كَانَ مذهبه إلا إثبات القدر.",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : ثقة.",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : صدوق.",3938],["أبو زرعة الرازي","قال أَبُو زُرْعَة ، وأَبُو حَاتِم ، وأَبُو دَاوُد، والنَّسَائي: ثقة.",3938],["أبو حاتم الرازي","قال أَبُو زُرْعَة ، وأَبُو حَاتِم ، وأَبُو دَاوُد، والنَّسَائي: ثقة.",3938],["أبو دواد السجستاني","قال أَبُو زُرْعَة ، وأَبُو حَاتِم ، وأَبُو دَاوُد، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","قال أَبُو زُرْعَة ، وأَبُو حَاتِم ، وأَبُو دَاوُد، والنَّسَائي: ثقة.",3938],["أبو حاتم الرازي","زاد أَبُو حَاتِم: لا بأس به.",3938],["يحيى بن معين","وَقَال أَبُو بَكْر بْن أَبي خيثمة ، عَن يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صدوق، ثقة، حسن الحَدِيث، وأَبُو نعيم أتقن منه، وعُبَيد اللَّه أثبتهم فِي إسرائيل، كَانَ إسرائيل يأتيه فيقرأ عَلَيْهِ الْقُرْآن",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي : ثقة، وكَانَ عالما بالقرآن، رأسا فيه.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة.",3938],["أبو دواد السجستاني","وَقَال أَبُو حاتم : لا بأس به .",3938],["أحمد بن حنبل","قال أبو طالب ، عَن أحمد بْن حنبل: لَيْسَ بمحكم الحَدِيث، يكتب حَدِيثه للمعرفة.",3938],["عثمان بن سعيد الدارمي","وَقَال عثمان بْن سَعِيد الدارمي ، عَن يحيى: ليس بشيءٍ .",3938],["عمرو بن علي الفلاس","وَقَال عَمْرو بْن عَلِي ، والنَّسَائي : متروك الحَدِيث.",3938],["أحمد بن شعيب النسائي","وَقَال عَمْرو بْن عَلِي ، والنَّسَائي : متروك الحَدِيث.",3938],["يحيى بن معين","قال إِسْحَاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","قال أبو حاتم : صدوق.",3938],["العباس الدوري","قال عَبَّاس الدُّورِيُّ : قيل ليحيى بْن مَعِين: يَعْلَى بْن عُبَيد عَن أَبِيهِ؟ قال: ثقة.",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي : كوفي ثقة.",3938],["أحمد بن صالح الجيلي","قال أَحْمَد بْن عَبد اللَّهِ العِجْلِيّ : كوفي تابعي ثقة .",3938],["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3938],["أبو زرعة الرازي","قال أَبُو زُرْعَة ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","قال أَبُو زُرْعَة ، والنَّسَائي: ثقة.",3938],["أبو حاتم الرازي","زاد أَبُو حاتم: صدوق.",3938],["أبو دواد السجستاني","وَقَال أَبُو دَاوُد: قال يَحْيَى بْن سَعِيد: عُبَيد أَبُو الْحَسَنِ مِمَّن لَمْ يدركه سُفْيَان من مشايخ الكوفيين، وسُفْيَان يَقُول: أدركناه.",3938],["محمد بن سعد كاتب الواقدي","قال محمد بن سعد : كَانَ ثقة وليس بكثير الْحَدِيث.",3938],["يحيى بن معين","قال عَبد اللَّهِ بْن أحمد بْن حنبل : سألت يحيى بْن مَعِين عَنْ عُبَيد بْن سَعِيد القرشي، فَقَالَ: ثقة، لَيْسَ بِهِ بأس، قَدْ رأيته كَانَ أصغر من أَبِي أَحْمَد الزبيري وهُوَ أَخُو يَحْيَى بْن سَعِيد الأُمَوِي.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : لا أعلم فِي حَدِيثه إنكارا، يحول من كتاب\"الضعفاء\"الَّذِي ألفه الْبُخَارِي.",3938],["أبو زرعة الرازي","وَقَال أبو زرعة : لا بأس به.",3938],["أبو حاتم الرازي","قال أَبُو حَاتِم : صدوق.",3938],["أبو زرعة الرازي","قال إِسْحَاق بْن مَنْصُور عَن يحيى بْن مَعِين، وأبو زُرْعَة : ثقة.",3938],["محمد بن إسماعيل البخاري","قال الْبُخَارِي : قال لي محمد أبويحيى عن علي: حكى ابن جُرَيْج أَن عَبد اللَّهِ بْن عُبَيد بْن عُمَير لَمْ يسمع من أَبِيهِ شَيْئًا ولا يذكره.",3938],["أبو حاتم الرازي","قال أَبُو حاتم ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","قال أَبُو حاتم ، والنَّسَائي: ثقة.",3938],["أبو حاتم الرازي","زاد أبو حاتم: لا بأس به.",3938],["يحيى بن معين","قال عَبَّاس الدُّورِيُّ ، والغلابي عَنْ يحيى بْن مَعِين: ليس بثقة .",3938],["يحيى بن معين","وَقَال إِبْرَاهِيم بْن عَبد اللَّهِ بْن الجنيد ، عَنْ يحيى بْن مَعِين: كذاب.",3938],["علي بن الحسين بن حبان","وَقَال عَلِي بْن الحسين بْن حبان : وجدت في كتاب أبي بخط يده: قال أَبُو زَكَرِيَّا: عُبَيد بْن القاسم قرابة سُفْيَان الثَّوْرِي، كَانَ كذابا خبيثا يحدث في المسجد الجامع بالرصافة، وكَانَ يحدث بحَدِيث ابْن مَسْعُود: جبلت القلوب عَلَى حب من أَحْسَن إِلَيْهَا.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : واهي الحديث، حدث بأحاديث منكرة لا ينبغي أَن يحدث عَنْهُ.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ: ليس بشيءٍ .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي ، وأَبُو بَكْر الجعابي : متروك الحَدِيث.",3938],["أبو بكر الجعابي","وَقَال النَّسَائي ، وأَبُو بَكْر الجعابي : متروك الحَدِيث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: مَا أعلم أحدا رَوَى هَذَا الحَدِيث عَنْ سُفْيَان غَيْر الأشجعي وهُوَ حَدِيث غريب، والله أعلم.",3938],["يحيى بن معين","قال أَبُو بَكْر بْن أَبي خيثمة ، عَن يحيى بْن مَعِين: ثقة.",3938],["أحمد بن صالح الجيلي","قال أَحْمَد بْن عَبد الله العِجْلِيّ : كوفي تابعي ثقة، كَانَ مقرئ أَهل الكوفة فِي زمانه.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["أبو حاتم الرازي","قال أَبُو حاتم : صدوق.",3938],["أبو حاتم الرازي","قال أبو حاتم : ضعيف الحديث، وسمع منه عُمَر بْن شبة سنة ثمان وتسعين ومئة .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["أبو نصر بن ماكولا","قال أَبُو نصر بْن ماكولا : قال صاحب\"تاريخ بخارى\"مُحَمَّدُ بْنُ أَحْمَدَ بْنِ مُحَمَّدِ الْبُخَارِي غنجار: سمعت أبا بَكْر مُحَمَّد بْن خَالِد بْن الْحَسَن المطوعي يَقُول: سمعت أبا حاتم سهل بْن السري بْن الخضر الْحَافِظ يَقُول: عُبَيدة العمي هُوَ عُبَيدة بْن بلال، شيخ بصري قدم بخارى واستوطنها ومَاتَ بِهَا سنة ستين ومئة .",3938],["يحيى بن معين","وَقَال أحمد بْن سعد بْن أَبي مريم ، عَن يحيى بْن مَعِين: ثقة.",3938],["جعفر بن محمد الفريابي","وَقَال جَعْفَر بْن مُحَمَّد الفريابي ، عَنْ مُحَمَّد بْن عَبد الله بن عمار الموصلي : ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كان ثقة صَالِح الحَدِيث، صاحب نَحْو وعربية وقراءة للقرآن ، وكَانَ من أَهل الكوفة، فقدم بغداد أَيَّام هَارُون أمِير الْمُؤْمِنيِنَ فصيره مَعَ ابنه مُحَمَّد بْن هَارُون فلم يزل مَعَهُ حَتَّى مَاتَ.",3938],["يحيى بن معين","قال إِسْحَاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["يحيى بن معين","وَقَال مُعَاوِيَة بْن صَالِح ، عَنْ يحيى بْن مَعِين: ضعيف.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ليس بشيءٍ.",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : ضعيف الحديث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ضعيف، وكَانَ قَدْ تغير.",3938],["أحمد بن حنبل","قال أبو طالب ، عَن أحمد بْن حنبل: لَهُ أحاديث منكرة.",3938],["يحيى بن معين","وَقَال أَبُو بَكْر بْن أَبي خيثمة، عَن يحيى بْن مَعِين: كثير الخطأ والوهم، متروك الحديث.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: ضعيف.",3938],["عمرو بن علي الفلاس","وَقَال عَمْرو بْن عَلِي : صدوق، كثير الخطأ والوهم، متروك الحديث.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم ، والدارقطني : ضعيف الحَدِيث.",3938],["أبو حاتم الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم ، والدارقطني : ضعيف الحَدِيث.",3938],["الدارقطني","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم ، والدارقطني : ضعيف الحَدِيث.",3938],["أبو حاتم الرازي","زاد أَبُو حَاتِم: منكر الْحَدِيث.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : منكر الحديث .",3938],["أبو دواد السجستاني","وَقَال أبو داود: ضعيف الحديث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بثقة.",3938],["أبو دواد السجستاني","قال أَبُو دَاوُد: سَعِيد لَمْ يسمع من عتاب شَيْئًا.",3938],["أبو عيسى الترمذي","وَقَال التِّرْمِذِيّ: حسن غريب، وقَدْ رُوِيَ عَنِ ابْن جُرَيْج، عَنِ ابْن شهاب، عَنْ عروة، عَنْ عَائِشَةَ، وسألت محمدا عَنْ هَذَا، فَقَالَ: حَدِيث ابْن جُرَيْج غَيْر محفوظ، وحَدِيث سَعِيد عَنْ عتاب أصح. ورَوَى لَهُ ابْن مَاجَهْ حَدِيثًا آخَرَ مِنْ رِوَايَةِ ليث بْن أَبي سليم، عَن عَطَاء، عَنْ عتاب بْن أسيد لما بعثه النَّبِيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى مَكَّة نهاه عَنْ شف مَا لَمْ يضمن. وهذا جميع ماله عندهم، والله أعلم.",3938],["أحمد بن حنبل","قال أبو طالب : سئل أحمد بْن حنبل عَنْ عتاب بْن بشير، فَقَالَ: أرجو أَن لا يَكُون بِهِ بأس. رَوَى بأخرة أحاديث منكرة، ومَا أرى أَنَّهَا إلا من قبل خصيف .",3938],["أحمد بن حنبل","وَقَال إبراهيم بْن يعقوب الجوزجاني ، عن أحمد بن حنبل: أحاديث عتاب عَنْ خصيف منكرة.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : ثقة.",3938],["يحيى بن معين","قال إِسْحَاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["محمود بن خالد","قال محمود بْن خَالِد السلمي : سمعت مَرْوَان بْن مُحَمَّد الطاطري يَقُول: عتبة بْن أَبي حَكِيم ثقة، من أَهل الأردن.",3938],["يحيى بن معين","وَقَال أَبُو بَكْر بْن أَبي خيثمة ، عَن يحيى بْن مَعِين: ضعيف.",3938],["أحمد بن حنبل","وَقَال عَبْد الرَّحْمَنِ بْن أَبي حَاتِم : سمعت أَبِي يَقُول: كَانَ أَحْمَد بْن حنبل يوهنه قليلا. قال: وسئل أَبِي عَنْهُ، فَقَالَ: صَالِح لا بأس بِهِ.",3938],["عثمان بن سعيد الدارمي","وَقَال عثمان بْن سَعِيد الدارمي، عَنْ دحيم: روى عنه الشيوخ، لا أعلمه إلا مستقيم الحَدِيث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ضعيف.",3938],["ابن عدي","قال ابْن عدي : روى عنه صدقة بْن خَالِد، وإِسماعيل بْن عياش، وبقية، وغيرهم. وكل واحد مِنْهُم يَرْوِي أحاديث عداد، وأرجو إنه لا بأس بِهِ.",3938],["الخطيب البغدادي","وَقَال أَبُو عَلِي النيسابوري الْحَافِظ، وأَبُو بَكْر الخطيب: ثقة وذكره ابنُ حِبَّان في كتاب \"الثقات\" .",3938],["أحمد بن حنبل","قال أَبُو طالب : سألت أَحْمَد بْن حنبل عَنْ عتبة أَبِي معاذ، فَقَالَ: هُوَ عتبة بْن حميد الَّذِي روى عنه الأشجعي، وكَانَ من أَهل البصرة وكتب من الحَدِيث شَيْئًا كثيرا. فَقُلْتُ: كَيْفَ حَدِيثه؟ فَقَالَ: ضعيف، لَيْسَ بالقوي، ولَمْ يشته النَّاس حَدِيثه.",3938],["أبو بكر الأثرم","وَقَال أَبُو بكر الأثرم ، عن محمد بْن حنبل: ثقة.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي : ثقة.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي فِي \"الكنى\"وأَبُو زحارة: عتبة بْن يقظان غَيْر ثقة.",3938],["محمد بن سعد كاتب الواقدي","قال مُحَمَّد بْن سَعْد : روى عَن أَبِي بْن كعب وغيره، وكَانَ ثقة قليل الحديث.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صدوق، وهو أحب إلي من يحيى بن عيسى الرملي.",3938],["علي بن المديني","وَقَال صَالِح بْن أَحْمَد بْن حنبل ، عَنْ علي بْن المديني: سألت يحيى، يَعْنِي: الْقَطَّان، عَن عُثْمَان بْن الأسود، فَقَالَ: كَانَ ثقة ثبتا .",3938],["أحمد بن حنبل","وَقَال أَبُو بَكْر الأثرم ، عَن أحمد بْن حنبل: ثقة.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : ثقة لا بأس بِهِ.",3938],["أبو حاتم الرازي","قال أَبُو حاتم : كَانَ شَرِيكا لشعبة، وهُوَ ثقة صدوق.",3938],["أبو زرعة الرازي","قال أَبُو زُرْعَة : يماني حميري ثقة.",3938],["أبو زرعة الدمشقي","وَقَال أَبُو زُرْعَة الدمشقي : قُلْت لابن مسهر: ما تقول في ابن علاق؟ قال: كَانَ ثقة، من طلبة العلم، ونسبه لنا، فَقَالَ: عُثْمَان بْن حصن بْن عُبَيدة بْن علاق.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة الرازي : لا بأس به.",3938],["أبو دواد السجستاني","وَقَال أَبُو دَاوُدَ ثقة. وذكره ابنُ حِبَّان فِي كتاب \"الثقات\" وَقَال: مستقيم الحَدِيث.",3938],["أبو حاتم بن حبان البستي","وَقَال أَبُو دَاوُدَ ثقة. وذكره ابنُ حِبَّان فِي كتاب \"الثقات\" وَقَال: مستقيم الحَدِيث.",3938],["أحمد بن حنبل","وَقَال أبو طالب ، عَن أحمد بْن حنبل: ثقة ثبت",3938],["مالك بن أنس","وَقَال عَبد اللَّهِ بن وهب : حَدَّثَنَا مَالِك أَن ابْن حيان المري إذ كَانَ أميرا عَلَى الْمَدِينَة، وعظ مُحَمَّد بْن المنكدر وأَصْحَابه نفرا فِي شَيْء بلغهم من أمر الحمامات وكَانَ فيهم مولى لابن حيان، فرفع ذَلِكَ إِلَى ابْن حيان، فبعث إِلَى مُحَمَّد بْن المنكدر وأَصْحَابه فضربهم لما كَانَ من كلامهم بالمعروف ونهيهم عَنِ المنكر، وَقَال: تتكلمون فِي مثل هَذَا؟ قال: فَقُلْتُ لمالك: وضرب ابْن المنكدر؟ قال إي والله وربيعة أَيْضًا، وكَانَ أحد المفتين ضرب وحلق رأسه ولحيته ولكن فِي شَيْء غَيْر هَذَا.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: لَيْسَ بثقة.",3938],["الحاكم","وَقَال الحاكم أَبُو أَحْمَد: منكر الحَدِيث.",3938],["ابن شهاب الزهري","قال عَبَّاس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي : عُثْمَان بْن زائدة ثقة، رجل صَالِح.",3938],["معمر بن راشد","وَقَال عَبد المجيد بْن عَبْد الْعَزِيزِ بْن أَبي رواد، عَنْ مَعْمَر: أَخْبَرَنِي رجل من أَهل الشام من أَهل الخير والصلاح إِن شاء اللَّه حَدِيثا يذكره عَنِ الْحَارِث بْن رافع، عَن أَبِيهِ، وسمع منه بقية فِي حدود سنة ثمان وعشرين ومئة.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : لين.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس ثقة .",3938],["أحمد بن حنبل","قال عَبد اللَّهِ بْن أَحْمَد بْن حنبل ، عَن أبيه: ثقة.",3938],["أبو حاتم الرازي","قال أَبُو حاتم : لا بأس بِهِ .",3938],["أحمد بن حنبل","قال صَالِح بْن أَحْمَد بْن حنبل ، عَن أَبِيهِ: ثقة.",3938],["محمود بن خالد","وَقَال مَحْمُود بْن خالد ، عَنْ مروان بْن مُحَمَّد: عُثْمَان بْن أَبي سودة وزِيَاد بْن أَبي سودة من أَهل بَيْت المقدس ثقتان ثبتان.",3938],["الخطيب البغدادي","وَقَال مُحَمَّد بْن إِسْحَاق الثقفي، وأَبُو بَكْر الخطيب : كَانَ ثقة.",3938],["عثمان بن سعيد الدارمي","وَقَال عثمان بْن سَعِيد الدارمي، عَن يحيى: ليس بشيءٍ .",3938],["إسحاق بن سيار النصيبي","وَقَال أَبُو جَعْفَر العقيلي: بلغني عَنْ إِسْحَاق بن سيار النصيبي، قال: سمعت أبا مسهر يَقُول: عُثْمَان بْن أَبي العاتكة ضعيف الحَدِيث.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : سمعت دحيما يَقُول: عُثْمَان بْن أَبي العاتكة لا بأس بِهِ.",3938],["يعقوب بن سفيان","وَقَال يعقوب بْن سفيان: ضعيف الحديث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ضعيف.",3938],["أبو زرعة الدمشقي","وَقَال أَبُو زُرْعَة الدمشقي : حَدَّثَنِي مُحَمَّد بْن العلاء شيخ من أَهل الْمَسْجِد قَدْ أدرك الأَوزاعِيّ وسَعِيد بْن عَبْد الْعَزِيز قديم. ثُمَّ قال: رأيت عُثْمَان بْن أَبي العاتكة يقص عَلَى النَّاس، مَاتَ وعلينا الفضل بن صالح، واينا سنة تسع وأربعين ومئة، تسع سنين.",3938],["خليفة بن خياط","وَقَال خليفة بن خياط : سنة خمس وخمسين ومئة، فِيهَا مَاتَ عُثْمَان بْن أَبي العاتكة مولى عُمَر بْن الْخَطَّاب وكَانَ ثقة فِي الحَدِيث .",3938],["عبد الرحمن بن مهدي","وَقَال أَبُو بَكْر بْن أَبي الأسود، عن عبد الرحمن بْن مهدي: لم يكن بالكوفة أثبت من أربعة، فبدأ بمنصور، وأَبُو حصين، وسلمة بْن كهيل، وعَمْرو بْن مرة .",3938],["عبد الرحمن بن مهدي","وَقَال الْحَارِث بْن سريج النقال، عَنْ عَبْد الرَّحْمَنِ بْن مهدي: لا ترى حافظا يختلف عَلَى أَبِي حصين.",3938],["يعقوب بن سفيان","وَقَال يعقوب بْن سفيان : حَدَّثَنَا أَبُو نعيم، قال: حَدَّثَنَا سفيان عَن أَبِي حصين، أسدي، شريف، ثقة ثقة كوفي.",3938],["مسعر بن كدام الكوفي","وَقَال مسعر: بعث بَعْض الأمراء إِلَى أبي حصين بألفي درهم وهُوَ عائل ، فردها فَقُلْتُ لَهُ: لَمْ رددتها؟ قال: الحياء والتكرم، وفِي رواية قال: قلتُ لأبي حصين: لَمْ رددت جائزة وهب بْن جَابِر؟ وَقَال سُفْيَان بْن عُيَيْنَة : كَانَ أَبُو حصين إِذَا سئل عَنْ مسألة قال: لَيْسَ لي بِهَا والله علم. وفي رواية: ليس بِهَا علم، والله أعلم.",3938],["أبو زرعة الرازي","قال أَبُو زُرْعَة ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","قال أَبُو زُرْعَة ، والنَّسَائي: ثقة.",3938],["الحاكم","وَقَال الحاكم أَبُو عَبْد اللَّهِ الْحَافِظ: ثقة مأمون.",3938],["أبو القاسم الطبراني","وَقَال أَبُو الْقَاسِمِ الطَّبَرَانِي: أخبرنا عُثْمَان بْن خرزاذ فِي كتابه وقَدْ رأيته دَخَلَ أنطاكية فدخلنا عَلَيْهِ وهُوَ عليل مسبوت فلم أسمع منه شَيْئًا وعاش بَعْد خروجي من أنطاكية ثَلاث (سنين؟) ونيف.",3938],["أبو حاتم الرازي","قال أَبُو حاتم : ثقة.",3938],["يحيى بن معين","قال إِبْرَاهِيم بْن عَبد اللَّهِ بْن الجنيد ، عَنْ يحيى بْن مَعِين: لا يكتب حَدِيثه، كَانَ يكذب.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَن يحيى بن مَعِين: ضعيف.",3938],["علي بن المديني","وَقَال عَلِي بْن المديني : ضعيف جدا.",3938],["يعقوب بن سفيان","وَقَال يَعْقُوب بْن سُفْيَان : لا يكتب حَدِيثه أَهل العلم إلا للمعرفة، ولا يحتج بروايته .",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِمٍ : مَتْرُوكُ الْحَدِيثِ، ذاهب .",3938],["أبو دواد السجستاني","وَقَال أَبُو دَاوُدَ : ليس بشيءٍ.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : متروك.",3938],["يحيى بن معين","وَقَال عَبْد الرَّحْمَنِ بْن أَبي حاتم : ذكره أبي عن إسحاق بْن منصور عَن يحيى بْن مَعِين أَنَّهُ قال: عُثْمَان بْن عَبْد الرَّحْمَنِ التَّيْمِيّ ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : منكر الحديث.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : لا بأس به.",3938],["يحيى بن معين","قال أبو بكر بْن أَبي خيثمة ، عَن يحيى بْن مَعِين: ثقة.",3938],["يحيى بن معين","وَقَال إِبْرَاهِيم بْن عَبد اللَّهِ بْن الجنيد : سألت يحيى بْن مَعِين عَنْ عُثْمَان بْن عَطَاء الخراساني، فَقَالَ: هُوَ ضعيف الحَدِيث.",3938],["يحيى بن معين","وَقَال مُحَمَّد بْن عُثْمَان بْن أَبي شَيْبَة ، عَن يحيى بْن مَعِين: كَانَ ضعيفا.",3938],["يحيى بن معين","وَقَال معاوية بْن صَالِح ، عَنْ يحيى بْن مَعِين: ضعيف.",3938],["يحيى بن معين","وَقَال المفضل بْن غسان الغلابي، عَن يحيى بْن مَعِين: خليد بْن دعلج، وسَعِيد بْن بشير، وعثمان بْن عَطَاء يضعفون.",3938],["عمرو بن علي الفلاس","وَقَال مُحَمَّد بْن إِبْرَاهِيم بْن شعيب الغازي، عَنْ عَمْرو بْن عَلِي : منكر الحديث.",3938],["الدارقطني","وَقَال مُسْلِم ، والدارقطني : ضعيف الحَدِيث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : يكتب حديثه ولا يحتج به.",3938],["أحمد بن حنبل","قال عَبد اللَّهِ بْن أَحْمَد بْن حنبل ، عَن أَبِيهِ: رجل صَالِح ثقة.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، وعثمان بْن سَعِيد الدارمي عَن يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صدوق، وكان يحيى بْن سَعِيد لا يرضاه.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : عُثْمَان والوليد ابنا عَمْرو بْن ساج يكتب حَدِيثهما ولا يحتج بِهِ.",3938],["أحمد بن حنبل","قال عَبد اللَّهِ بْن أَحْمَد بْن حنبل : قال أَبِي: عُثْمَان بْن عُمَير أَبُو اليقظان، ويُقال: عُثْمَان بْن قَيْس، وهُوَ ضعيف الحَدِيث.",3938],["أحمد بن حنبل","وَقَال أحمد بن حنبل : ثقة، وكَانَ يرى الإرجاء.",3938],["يحيى بن معين","وَقَال يَحْيَى بْن مَعِين ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال يَحْيَى بْن مَعِين ، والنَّسَائي: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صدوق.",3938],["أبو حاتم الرازي","قال أَبُو حاتم : رَوَى حَدِيثا منكرا عَنْ جَعْفَر بْن مُحَمَّد (ت)، عَنْ عُبَيد اللَّه بْن أَبي رافع، عَنْ شقران: ألقى فِي قبر النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قطيفة حمراء.",3938],["يحيى بن معين","وَقَال فضلك الرَّازِي : سألت يَحْيَى بْن مَعِين عَنْ مُحَمَّد بْن حميد الرَّازِي، فَقَالَ: ثقة.",3938],["يحيى بن معين","وَقَال عَلِي بْن الْحُسَيْن بْن حبان : وجدت فِي كتاب أبي بخط يده عَن يحيى بْن مَعِين، قال: ابني أَبِي شَيْبَة: عُثْمَان وعبد اللَّه ثقتين صدوقين لَيْسَ فيهما شك.",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد اللَّهِ العجلي : عَبد اللَّهِ بْن مُحَمَّد بن أَبي شَيْبَة، كوفي ثقة، وأخوه عُثْمَان كوفي ثقة.",3938],["الدارقطني","وَقَال أَبُو الْحَسَنِ الدارقطني فِي كتاب\"التصحيف وأخبار المصحفين\": حَدَّثَنَا أَبُو الْقَاسِمِ عَلِي بْن مُحَمَّد بْن كاس النخعي القاضي، قال: حَدَّثَنَا إبراهيم بْن عبد اللَّهِ الخصاف، قال: قرأ عَلَيْنَا عُثْمَانَ بْن أَبي شَيْبَة فِي التفسير فلما جهزهم بجهازهم جعل السفينة في رحل أخيه.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بن مَعِين: ثقة.",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة : لا بأس به.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : يكتب حديثه.",3938],["أحمد بن حنبل","قال إِبْرَاهِيم بْن يعقوب الجوزجاني ، عن أَحْمَد بْن حنبل: صدوق ثقة .",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سَعْد : عُثْمَان البتي وهُوَ ابْن مُسْلِم بن جرموز وكَانَ ثقة له أحاديث، وكَانَ صاحب رأي وفقه.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : شيخ يكتب حَدِيثه.",3938],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ : ثقة.",3938],["يحيى بن معين","وَقَال مُحَمَّد بْن عُثْمَانَ بْن أَبي شَيْبَة ، عَن يحيى بْن مَعِين: كَانَ ضعيفا ضعيفا.",3938],["يحيى بن معين","وَقَال أحمد بْن سعد بْن أَبي مريم ، عَن يحيى بْن مَعِين: ضعيف لا يكتب حديثه.",3938],["يحيى بن معين","وَقَال الْحُسَيْن بْن الْحَسَن الرازي ، عَنْ يحيى بْن مَعِين: ليس بشيءٍ .",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : ضعيف الْحَدِيث.",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : ضعيف الحديث، منكر الحَدِيث، أشبه حَدِيثه بحَدِيث يُوسُف بْن عطية.",3938],["أبو دواد السجستاني","وَقَال أَبُو داود ، والنَّسَائي : ضعيف.",3938],["أحمد بن شعيب النسائي","وَقَال أَبُو داود ، والنَّسَائي : ضعيف.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي فِي موضع آخر: ليس بثقة.",3938],["أحمد بن حنبل","قال صَالِح بْن أَحْمَد بْن حنبل : قال أَبِي: عُثْمَان بْن الْمُغِيرَة هُوَ عُثْمَان بْن أَبي زرعة وهُوَ عُثْمَان الأعشى، وهُوَ عُثْمَان الثقفي كوفي ثقة، لَيْسَ أحد أروى عنه من شَرِيك.",3938],["يحيى بن معين","وَقَال أَحْمَد بْن أَبي خيثمة : سئل يَحْيَى بْن مَعِين عَنْ عُثْمَان بْن الْمُغِيرَة، فَقَالَ: هُوَ عُثْمَان بْن أَبي زرعة الثقفي، وهُوَ ثقة.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال أبو حاتم ، والنَّسَائي: ثقة.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["أبو زرعة الرازي","وَقَال إسحاق بْن مَنْصُور عَنْ يحيى بْن مَعِين، وأبو زُرْعَة : ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: لا بأس به.",3938],["أحمد بن حنبل","قال عَبد الله بْن أحمد بْن حنبل ، عَن أبيه: ثقة.",3938],["محمد بن علي الصوري","قال الحافظ أبو عَبْد الله مُحَمَّد بْن عَلِي الصوري : أنا رأيت قبورهم بقرقيسيا. روى له الْجَمَاعَة. ٣٨٨٥ - د س ق: عدي بن دِينَار المدني ، مولى أم قَيْس بِنْت محصن أخت عكاشة بْن محصن الأسدي. روى عن: أَبِي سُفْيَان بْن محصن، ومولاته أم قَيْس بِنْت محصن (د س ق) . رَوَى عَنه: أَبُو المقدام ثابت بْن هرمز الحداد (د س ق)، وصالح مولى التوأمة.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سَعْد : كَانَ ناسكا فقيها، وهُوَ صاحب عُمَر بْن عَبْد الْعَزِيز، وولي الجزيرة وأرمينية وأذربيجان لسُلَيْمان بْن عَبد المَلِك، وكَانَ ثقة إن شاء اللَّه.",3938],["يحيى بن معين","قال عَبَّاس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ضعيف.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: ليس بثقة .",3938],["أبو دواد السجستاني","وَقَال أَبُو دَاوُد : ضعيف.",3938],["علي بن الحكم","وَقَال النَّسَائي: ليس بثقة .",3938],["علي بن الحسين بن حبان","قال علي بْن الحسين بْن حبان: وجدت فِي كتاب أَبِي بخط يده. قال أبو زكريا، يَعْنِي يَحْيَى بْن مَعِين: عدي بْن الفصيل ثقة، حدث عَنْهُ معتمر والأَصْمَعِيّ.",3938],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ : لا بأس بِهِ.",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبد الله العجلي : تابعي ثقة من خيار التابعين.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم : ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم : ثقة.",3938],["يحيى بن معين","قال عثمان بن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: ثقة.",3938],["يحيى بن معين","وَقَال عثمان بن سَعِيد الدارمي عَن يحيى بْن مَعِين وعن دحيم: ثقة.",3938],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ : لا بأس به.",3938],["أحمد بن صالح الجيلي","وَقَال أحمد بن عبد الله العجلي : مدني تابعي ثقة، وكان رجلا صالحا لم يدخل في شيء من الفتن.",3938],["بشر بن المفضل","وَقَال عثمان بن عبد الحميد بن لاحق ابن عم بشر بن المفضل بن لاحق، عَن أبيه: قال عُمَر بن عبد العزيز: ما أحد أعلم من عروة بن الزبير وما أعلمه يعلم شيئا أجهله.",3938],["ابن شهاب الزهري","وَقَال يونس بن يزيد، عن الزُّهْرِيّ: كان عروة بحرا لا تكدره الدلاء، وما رأيت أغزر حديثا من عُبَيد الله بن عبد الله .",3938],["سفيان بن عيينة","وَقَال خالد بن نزار ، عن سفيان بْن عُيَيْنَة: كان أعلم الناس بحديث عائشة ثلاثة: القاسم بن محمد، وعروة بن الزبير، وعُمَرة بنت عبد الرحمن.",3938],["عبد الرحمن بن أبي الزناد","وَقَال عبد الرحمن بْن أَبي الزناد، عَن أبيه: ما رأيت أحدا أروى للشعر من عروة.",3938],["ابن شهاب الزهري","وَقَال يعقوب بن سفيان ، عن عيسى بن هلال السليحي، عَن أبي حيوة شريح بن يزيد، عن شعيب بن أَبي حمزة، عن الزُّهْرِيّ، عن عروة: كنت غلاما لي ذؤابتان فقمت أركع ركعتين بعد العصر فبصر بي عُمَر بن خطاب ومعه الدرة، فلما رأيته فررت منه فأحضر في طلبي حتى تعلق بذؤابتي.",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة : ثقة.",3938],["أبو زرعة الرازي","قال أبو زُرْعَة ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","قال أبو زُرْعَة ، والنَّسَائي: ثقة.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : عروة بن عياض سمع ابن عُمَر ، سمع منه ابن جُرَيْج مرسل ، روى عنه ابن أَبي مليكة وعَمْرو بن دينار.",3938],["سفيان بن عيينة","وَقَال ابن عُيَيْنَة، عن عَمْرو: أخبرني عروة بن عياض ، قال: نزل علينا أبو سَعِيد.",3938],["الزبير بن بكار","وَقَال الزبير بْن بكار فِي ذكر ولد عياض بن عدي بن الخيار: فولد عياض بن عدي عديا وبه كان يكنى، ولم يذكر له ولدا غيره، فالله أعلم .",3938],["أحمد بن صالح الجيلي","وَقَال أَحْمَد بْن عَبْد اللَّهِ العجلي : كوفي تابعي ثقة.",3938],["أبو عيسى الترمذي","وَقَال التِّرْمِذِيّ عقيب الحديث الأول : سمعت محمد بن إسماعيل يضعف هذا الحديث وَقَال: حبيب بن أَبي ثابت لم يسمع من عروة.",3938],["أحمد بن حنبل","قال أبو بكر بْن أَبي خيثمة : سألت أحمد بن حنبل ويحيى بن مَعِين عَن أبي عمار، فقالا: اسمه عريب بن حميد، وهو كوفي ثقة .",3938],["أبو حاتم الرازي","وَقَال أبو حاتم لَيْسَ بِهِ بأس. وذكره ابنُ حِبَّان فِي كتاب \"الثقات\" . روى له أبو داود في كتاب\"القَدَر\"، والباقون. • عزرة بن سَعِيد، ويُقال: عروة بن سَعِيد. تقدم . ٣٩٢٠ - م د ت س: عزرة بن عبد الرحمن بن زرارة الخزاعي الكوفي الأعور. . روى عن: أبي الشعثاء جَابِر بْن زيد، والحسن العرني (م س)، وحميد بْن عَبْد الرحمن الحميري (م ت س)، وراشد بن حبيش، وقيل: ابن خنبش الحمصي، وسَعِيد بْن جبير (م د ق)، وسَعِيد بْن عَبْد الرحمن بن أبزى (د ت س)، وعامر الشعبي، وعائشة أم المؤمنين (س) مرسل.",3938],["أبو حاتم بن حبان البستي","وَقَال أبو حاتم لَيْسَ بِهِ بأس. وذكره ابنُ حِبَّان فِي كتاب \"الثقات\" . روى له أبو داود في كتاب\"القَدَر\"، والباقون. • عزرة بن سَعِيد، ويُقال: عروة بن سَعِيد. تقدم . ٣٩٢٠ - م د ت س: عزرة بن عبد الرحمن بن زرارة الخزاعي الكوفي الأعور. . روى عن: أبي الشعثاء جَابِر بْن زيد، والحسن العرني (م س)، وحميد بْن عَبْد الرحمن الحميري (م ت س)، وراشد بن حبيش، وقيل: ابن خنبش الحمصي، وسَعِيد بْن جبير (م د ق)، وسَعِيد بْن عَبْد الرحمن بن أبزى (د ت س)، وعامر الشعبي، وعائشة أم المؤمنين (س) مرسل.",3938],["أبو دواد السجستاني","وَقَال أبو حاتم لَيْسَ بِهِ بأس. وذكره ابنُ حِبَّان فِي كتاب \"الثقات\" . روى له أبو داود في كتاب\"القَدَر\"، والباقون. • عزرة بن سَعِيد، ويُقال: عروة بن سَعِيد. تقدم . ٣٩٢٠ - م د ت س: عزرة بن عبد الرحمن بن زرارة الخزاعي الكوفي الأعور. . روى عن: أبي الشعثاء جَابِر بْن زيد، والحسن العرني (م س)، وحميد بْن عَبْد الرحمن الحميري (م ت س)، وراشد بن حبيش، وقيل: ابن خنبش الحمصي، وسَعِيد بْن جبير (م د ق)، وسَعِيد بْن عَبْد الرحمن بن أبزى (د ت س)، وعامر الشعبي، وعائشة أم المؤمنين (س) مرسل.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عن يحيى بن مَعِين: عزرة الذي يروي عنه قتادة ثقة.",3938],["علي بن المديني","وَقَال أَبُو الحسن بْن البراء ، عن علي بن المديني: عزرة بن عبد الرحمن ثقة، روى عنه قتادة، والتَّيْمِيّ، وعبد الكريم الجزري غيرهم، ولم يسمع من البراء .",3938],["يحيى بن معين","وَقَال إسحاق بن مَنْصُور ، عَنْ يحيى بْن مَعِين: ضعيف.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بالقوي وَقَال أَبُو حاتم : منكر الْحَدِيث.",3938],["يحيى بن معين","قال عباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ليس بشيءٍ.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : ضعيف الحديث.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ: مجهول منكر الحديث .",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة ، وأَبُو حاتم : لا بأس به.",3938],["أبو حاتم الرازي","وَقَال أبو زُرْعَة ، وأَبُو حاتم : لا بأس به.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["أبو حاتم الرازي","قال أَبُو حاتم : صدوق.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة.",3938],["أبو دواد السجستاني","قال أبو طالب عَن أحمد بْن حنبل، وأَبُو دَاوُدَ : ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كان من مولدي الجند، ونشأ بمكة، وهو مولى لبني فهر أو الجمح، وانتهت فتوى أهل مكة إليه وإلى جاهد في زمانهما، وأكثر ذلك إلى عطاء. سمعت بعض أهل العلم يقول: كان عطاء أسود أعور أفطس أشل أعرج ثم عمي بعد ذلك، وكان ثقة فقيها عالما كثير الحديث.",3938],["عطاء بن أبي رباح","قال أبو عَمْرو بن العلاء: قلت لعطاء: إنك يومئذ لخنشليل بالسيف. قال: إنهم دخلوا علينا.",3938],["مالك بن أنس","وَقَال عبد الله بن وهب ، عن مالك: قال عَمْرو بن دينار ومجاهد وغيرهما من أهل مكة: لم يزل شأننا متشابها متناظرين حتى خرج عطاء بن أَبي رباح إلى المدينة فلما رجع إلينا استبان فضله علينا.",3938],["إسماعيل بن أمية","وَقَال سفيان بن عُيَيْنَة ، عَنْ إِسْمَاعِيلَ بْنِ أمية: كان عطاء يطيل الصمت فإذا تكلم يخيل إلينا أنه يؤيد.",3938],["سفيان الثوري","وَقَال سفيان الثوري ، عن سلمة بن كهيل: ما رأيت أحدا يريد بهذا العلم وجه الله غير هؤلاء الثلاثة: عطاء، وطاوس، ومجاهد.",3938],["يعلى بن عبيد الطنافسي","وَقَال يَعْلَى بن عُبَيد الطنافسي دخلنا على محمد بن سوقة، فقال: يا ابن أخي أحدثكم بحديث لعله ينفعكم فقد نفعني، قال لنا عطاء بن أَبي رباح: إن من قبلكم كانوا يعدون فضول الكلام ما عدا كتاب الله أو أمر بمعروف أو نهي عن منكر أو أن تنطق في معيشتك التي لابد لك منها أتنكرون أن عليكم حافظين كراما كاتبين ﴿عن اليمين وعن الشمال قعيد ما يلفظ من قول إلا لديه رقيب عتيد) ﴿٢) أما يستحيي أحدكم لو نشرت صحيفته التي أملى صدر نهاره وليس فيها شيء من أمر آخرته.",3938],["يحيى بن سعيد القطان","وَقَال علي بن المديني ، عَن يحيى بْن سَعِيد القطان: مُرْسلًات مجاهد أحب إلي من مُرْسلًات عطاء بكثير، كان عطاء يأخذ عن كل ضرب.",3938],["أحمد بن حنبل","وَقَال الفضل بْن زياد ، عن أَحْمَد بْن حنبل: مُرْسلًات سَعِيد بن السميب أصح المُرْسلًات، ومُرْسلًات إبراهيم النخعي لا بأس بها، وليس في المُرْسلًات شيء أضعف من مُرْسلًات الْحَسَن وعطاء بْن أَبي رباح فإنهما كانا يأخذان عن كل أحد.",3938],["أحمد بن حنبل","وَقَال عَبْد اللَّهِ بْن أَحْمَد بن حنبل ، عَن أبيه: عطاء بن السائب ثقة ثقة رجل صالح.",3938],["أحمد بن حنبل","وَقَال أبو طالب ، عن أحمد بن حنبل: من سمع منه قديما كان صحيحا، ومن سمع منه حديثا لم يكن بشيءٍ، سمع منه قديما شعبة وسفيان، وسمع منه حديثا جرير وخالد بن عبد الله وإسماعيل وعلي بن عاصم، وكان يرفع عن سَعِيد بن جبير شيئا لم يكن يرفعها.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَن يحيى بن مَعِين: لم يسمع عطاء بن السائب من يَعْلَى بن مرة.",3938],["يحيى بن معين","وَقَال أبو أحمد بن عدي : أخبرنا ابن أَبي عصمة، قال: حَدَّثَنَا أَحْمَدُ بْنُ أَبي يَحْيَى، قال: سمعت يحيى بْن مَعِين يَقُول: ليث بن أَبي سليم ضعيف مثل عطاء بن السائب، وجميع من روى عن عطاء روى عنه في الاختلاط إلا شعبة وسفيان.",3938],["أحمد بن صالح الجيلي","وَقَال أحمد بن عبد الله العجلي : كان شيخا ثقة قديما، روى عن ابن أَبي أوفى، ومن سمع منه قديما فهو صحيح الحديث، منهم: سفيان الثوري.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة في حديثه القديم إلا أنه تغير، ورواية حماد بن زيد وشعبة وسفيان عنه جيدة.",3938],["الحميدي","وَقَال الحميدي ، عن سفيان: كنت سمعت من عطاء بن السائب قديما ثم قدم علينا قدمة فسمعته يحدث ببعض ما كنت سمعت، فخلط فيه فاتقيته واعتزلته.",3938],["يحيى بن سعيد القطان","وَقَال أبو النعمان ، عن يحيى بن سَعِيد القطان: عطاء بن السائب تغير حفظه بعد، وحماد، يعني ابن زيد - سمع منه قبل أن يتغير.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ليس بثقة.",3938],["عمرو بن علي الفلاس","وَقَال عَمْرو بْن علي : كان كذابا.",3938],["أبو زرعة الرازي","وَقَال أبو زُرْعَة : واسطي ضعيف.",3938],["أبو حاتم الرازي","وَقَال أَبُو حَاتِم : ضعيف الحديث، منكر الحديث جدا مثل أبان بن أَبي عياش وذا الضرب، وهو متروك الحديث.",3938],["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : منكر الحديث.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ليس بثقة، ولا يكتب حديثه .",3938],["أحمد بن حنبل","قال عَبْدُ اللَّهِ بْنُ أحمد بْن حنبل ، عَن أبيه: ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["يحيى بن معين","قال معاوية بْن صَالِح ، عَنْ يحيى بْن مَعِين: ليس به بأس، وأحاديثه منكرات.",3938],["يحيى بن معين","وَقَال عثمان بن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : كان شيخا صالحا يشبه يوسف بن أسباط وكان دفن كتبه فلا يثبت حديثه وليس بقوي.",3938],["يحيى بن معين","قال إسحاق بن منصور ، وعباس الدروي عَنْ يحيى بْن مَعِين: ثقة .",3938],["أبو دواد السجستاني","وَقَال أَبُو دَاوُدَ: لم يدرك ابن عباس ولم يره.",3938],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ: ثقة في نفسه إلا أنه لم يلق ابن عباس.",3938],["أبو نعيم الأصبهاني","وَقَال الحافظ أبو نعيم الأصبهاني: كان مولده سنة خمسين، ووفاته سنة خمس وثلاثين ومئة.",3938],["الخطيب البغدادي","وَقَال الحافظ أبو بكر الخطيب: كل حديث يرويه ابن جُرَيْج عن عطاء غير منسوب عن ابن عباس، ويذكر فيه سماع عطاء من ابن عباس فهو عطاء بن أَبي رباح، لأن عطاء الخراساني لم يسمع من ابن عباس ولا لقيه، وإنما كان يرسل الرواية عنه وقل حديث يرويه ابن جُرَيْج عن عطاء الخراساني إلا وهو يعرفه.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : صالح لا يحتج بحديثه، وكان قدريا.",3938],["يحيى بن معين","قال أَبُو بَكْر بْن أَبي خيثمة ، عن يحيى بن مَعِين: عطاء الكيخاراني ثقة .",3938],["علي بن المديني","قال علي بن المديني : سكن الرملة، وكان ثقة.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: عطاء بن يزيد، أبو يزيد شامي ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد ، والبخاري : سمع من ابن مسعود.",3938],["محمد بن إسماعيل البخاري","وَقَال مُحَمَّد بْن سعد ، والبخاري : سمع من ابن مسعود.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : لم يسمع منه.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد أيضا : سمع من أبي عبد الله الصنابحي، وأما مالك بن أنس فقال: عطاء بن يسار عَنْ عَبْدِ اللَّهِ الصُّنَابِحِيّ وكان ثقة، كثير الحديث.، أخبرنا مُحَمَّد بن عُمَر، قال: أَخْبَرَنَا أسامة بن زيد بن أسلم عَن أبيه، قال: توفي عطاء بن يسار سنة ثلاث أو أربع ومئة.",3938],["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة .",3938],["أبو القاسم الطبراني","قال أَبُو الْقَاسِمِ الطَّبَرَانِيُّ: ولا نَعْلَمُ هَذَا اللَّفْظَ يُروى عن رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلا بِهَذَا الإِسْنَادِ. رَوَاهُ التِّرْمِذِيّ أَتَمَّ مِنْ هَذَا عَنِ الْحَسَنِ بْنِ عَلِيٍّ، عَن أَبِي أُسَامَة، عَنْ عَبْد الحميد بْنِ جَعْفَرٍ وَقَال: حَسَنٌ. ورَوَاهُ مِنْ وجْهٍ آخَرَ مُرْسلًا.",3938],["أحمد بن حنبل","وَقَال أَبُو طالب : سألت أَحْمَد بن حنبل عن عطاف بن خالد، فقال: هو من أهل المدينة، ثقة صحيح الحديث.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَن يحيى بْن مَعِين: ليس به بأس، ثقة صالح الحديث .",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم: صدوق.",3938],["أحمد بن حنبل","وَقَال عبد الله بْن أحمد بْن حنبل عَن أبيه نحو ذلك. وَقَال: كان الثوري وهشيم يضعفان حديث عطية.",3938],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : لين.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : ضعيف، يكتب حديثه، وأبو نضرة أحب إلي منه.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ضعيف.",3938],["أحمد بن صالح الجيلي","قال أَحْمَد بْن عَبْد اللَّهِ العجلي : عفان بن مسلم بصري ثقة ثبت صاحب سنة، وكان على مسائل معاذ بن معاذ القاضي فجعل له عشرة آلاف دينار على أن يقف عن تعديل رجل فلا يقول عدل ولا غير عدل.",3938],["إبراهيم بن الحسين بن ديزيل","وَقَال إبراهيم بن الحسين بن ديزيل: لما دعي عفان للمحنة كنت آخذا بلجام حماره، فلما حضر عرض عليه القول، فامتنع أن يجيب، فقيل له: يحبس عطاؤك، قال: وكان يعطى في كل شهر ألف درهم - فقال: ﴿وفي السماء رزقكم وما توعدون﴾ قال: فما رجع إلى داره عذله نساؤه ومن في داره. قال: وكان في داره نحو أربعين إنسانا. قال: فدق عليه داق الباب فدخل عليه رجل شبهته بسمان أو زيات ومعه كيس فيه ألف درهم، فقال: يا أبا عثمان ثبتك الله كما ثبت الدين، وهذا في كل شهر.",3938],["علي بن الحسين بن حبان","وَقَال علي بْن الحسين بْن حبان : وجدت فِي كتاب أَبِي بخط يده: سألت أبا زكريا، يعني: يحيى بن مَعِين - قلت: إذا اختلفت أبو الوليد وعفان في حديث عن حماد بن سلمة فالقول قول من هو؟ قال: القول قول عفان. قلت: فإن اختلفوا في حديث عن شعبة؟ قال: القول قول عفان. قلت: وفي كل شيء قال: نعم، عفان أثبت منه وأكيس، وأبو الوليد ثقة ثبت.",3938],["المفضل بن غسان الغلابي","وَقَال المفضل بن غسان الغلابي : وذكر له، يعني: ليحيى بن مَعِين - عفان وثبته فقال: قد أخذت عليه خطأه في غير حديث.",3938],["جعفر بن محمد الصائغ","وَقَال عُمَر بن أحمد الجوهري : سمعت جَعْفَر بْن مُحَمَّد الصائغ يقول: اجتمع علي بن المديني، وأَبُو بَكْرِ بْنُ أَبي شَيْبَة، وأحمد بن حنبل، وعفان بن مسلم، فقال عفان: ثلاثة يضعفون في ثلاثة: علي بن المديني في حماد بن زيد، وأحمد بن حنبل في إبراهيم بن سَعْد، وأَبُو بَكْر بْن أَبي شَيْبَة في شَرِيك.",3938],["أحمد بن حنبل","وَقَال إسحاق بن الحسن الحربي : سمعت أحمد بن حنبل يقول: ما رأيت الألفاظ في كتاب أحد من أصحاب شعبة أكثر منها عند عفان، يعني أنبأنا وأخبرنا وسمعت وحَدَّثَنَا، يعني شعبة.",3938],["يحيى بن معين","وَقَال عَبْد الخالق بْن منصور : سئل يحيى بْن مَعِين عَن عفان وبهز أيهما كان أوثق؟ فقال: كلاهما ثقتان. فقيل له: إن ابن المديني يزعم أن عفان أصح الرجلين؟ فقال: كانا جميعا ثقتين صدوقين.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ : سمعت يحيى بْن مَعِين يقول: كان عفان أثبت من زيد بن الحباب فيما رويا.",3938],["يحيى بن معين","وَقَال محمد بن العباس النَّسَائي : سألت يحيى بن مَعِين، قلت: من أثبت: عبد الرحمن بن مهدي أو عفان؟ قال: كان عبد الرحمن أحفظ لحديثه وحديث الناس ولم يكن من رجال عفان في الكتاب، وكان عفان أسن منه بسنتين.",3938],["أبو حاتم بن حبان البستي","وَقَال ابن حبان : وجدت في كتابه أبي بخط يده: قال أبو زكريا: كان يحيى بن سَعِيد إذا تابعه عفان على شيء ثبت عليه وإن كان خطاء، وإذا خالفه عفان في حديث عن حماد رجع عنه يحيى لا يحدث به أصلا.",3938],["يحيى بن معين","وَقَال أيضا سمعت أَبَا عَبْد اللَّهِ مُحَمَّد بْن عَبْد الرَّحْمَنِ بْن فهم، قال: سمعت يحيى بن مَعِين يقول: عفان أثبت من عَبْد الرَّحْمَنِ بْن مهدي.",3938],["أبو حاتم الرازي","وَقَال أبو حاتم : عفان إمام ثقة متقن متين.",3938],["الخطيب البغدادي","قال الْحَافِظ أَبُو بَكْر الْخَطِيب : أما أبو نعيم فصحيح موته في سنة تسع عشرة، وأما عفان ففي سنة عشرين.",3938],["أحمد بن حنبل","قال أَحْمَد بْن أَبي يَحْيَى ، عن أَحْمَد بْن حنبل: ضعيف، منكر الحديث.",3938],["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي ، عَنْ يحيى بْن مَعِين: ليس بشيءٍ.",3938],["يحيى بن معين","وَقَال عَباس الدُّورِيُّ ، عَنْ يحيى بْن مَعِين: ليس بثقة .",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ليس بثقة ولا يكتب حديثه.",3938],["يحيى بن معين","قال المفضل بْن غسان الغلابي ، وأبو بكر بْن أَبي خيثمة عَنْ يحيى بْن مَعِين: ثقة .",3938],["عبد الرحمن بن يوسف بن خراش","وَقَال عَبْد الرَّحْمَنِ بْن يُوسُف بن خراش : صدوق من خيار الناس.",3938],["أحمد بن صالح الجيلي","قال أَحْمَد بْن عَبْد اللَّهِ العجلي : كوفي تابعي ثقة.",3938],["أحمد بن صالح الجيلي","وَقَال أحمد بن عبد الله العجلي : بصري تابعي ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كَانَ ثقة، قليل الحديث.",3938],["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة.",3938],["يحيى بن معين","قال إسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938],["أبو حاتم الرازي","وَقَال أَبُو حاتم : صدوق.",3938],["عبد الله بن أحمد بن حنبل","وَقَال عَبْد اللَّهِ بْن أَحْمَد بْن حنبل : سَأَلتُ أبي عن عقبة بن خالد. قلت: هو ثقة؟ قال: أرجو إن شاء الله.",3938],["عبد الله بن أحمد بن حنبل","قال عَبْد اللَّهِ بْن أَحْمَد بن حنبل : قلتُ لأبي عقبة بن سيار: أبو الجلاس ثقة؟ قال: أرجو.",3938],["يحيى بن معين","وَقَال إسحاق بن مَنْصُور ، عَنْ يحيى بْن مَعِين: أبوالجلاس ثقة.",3938],["أحمد بن صالح الجيلي","قال العجلي ، وأبو داود ، والنَّسَائي: ثقة.",3938],["أبو دواد السجستاني","قال العجلي ، وأبو داود ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","قال العجلي ، وأبو داود ، والنَّسَائي: ثقة.",3938],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : توفي فِي أول ولاية الحجاج عَلَى العراق وكان ثقة.",3938],["عمرو بن علي الفلاس","وَقَال عَمْرو بْن عَلِيّ : روى عن الحسن وعطاء، وكان ضعيفا واهي الحديث ليس بالحافظ، ما سمعت أحدا يحدث عنه إلا أبا قتيبة، سمعته مرة يقول: حَدَّثَنَا عقبة الرفاعي.",3938],["أبو دواد السجستاني","وَقَال أبو داود : ضعيف.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ليس بثقة.",3938],["محمد بن إسماعيل البخاري","قال البخاري : عقبة بن عبد الرحمن بن معمر عن ابن ثوبان، روى عنه ابن أَبي ذئب مرسل، عن النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ في مس الذكر، وزاد عَبْد اللَّهِ بن نافع : عن جابر، ولا يصح، أرى أخا عبد الله الأَنْصارِيّ وزيد.",3938],["أحمد بن صالح الجيلي","قال العجلي ، والنَّسَائي: ثقة.",3938],["أحمد بن شعيب النسائي","قال العجلي ، والنَّسَائي: ثقة.",3938],["المفضل بن غسان الغلابي","وَقَال المفضل بْن غسان الغلابي: حدثني أبو زكريا، قال: عقبة من أصحاب الأَوزاعِيّ دمشقي لا بأس به.",3938],["الحاكم","وَقَال الحاكم أَبُو عَبْد الله: ثقة مأمون.",3938],["أبو حاتم الرازي","قال أبو حاتم : ضعيف الحديث بين الضعف مثل الأصبغ بن نباتة، وأبي سَعِيد عقيصي متقاربان في الضعف لا يشتغل بِهِ .",3938],["أحمد بن صالح الجيلي","قال العجلي : مصري، تابعي، ثقة.",3938],["أحمد بن حنبل","وَقَال عَبْد اللَّهِ بْن أَحْمَد بن حنبل : قال أبي: لم يسمع هذا الكتاب، يعني: حديث شعبة من غندر - إلا أنا ويحيى وخلف وهيثم الزهراني وصدقة المروزي، قال: وكنا نزولا في دار إنسان يقال له: الرازي، فقال لنا: اذهبوا بابني معكم فلا أدري سمع الكتاب كله أو بعضه.",3938],["أبو دواد السجستاني","وَقَال أبو داود : عقبة بن مكرم العمي ثقة ثقة من ثقات الناس فوق بندار في الثقة عندي.",3938],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3938],["عبد الله بن عمر","قال أحمد بن علي الأبار، عن عبد الله بن عُمَر الكوفي: ثقة.",3938],["يحيى بن معين","قال إسحاق بن منصور ، عَنْ يحيى بْن مَعِين: ثقة .",3938],["يحيى بن معين","قال إسحاق بْن مَنْصُور ، عَنْ يحيى بْن مَعِين: ثقة.",3938]],"4535":[["يحيى بن معين","قال أحمد بن سعد بْن أَبي مريم ، عَن يحيى بْن مَعِين: ثقة، حجة .",3368],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3368]],"4574":[["يحيى بن معين","قال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة.",3404]],"4593":[["عبد الله بن المبارك","وَقَال ابْنُ المبارك أَيْضًا: عن فليح بن سُلَيْمان: سمعت عباس بن سهل يحدث فلم احفظه، أراه حدثنيه، أراه ذكر عن عِيسَى بْن عَبد اللَّهِ إنه سمع من عباس بن سهل، فذكره.",3424],["يحيى بن معين","وَقَال إسحاق بْن منصور وعثمان بْن سَعِيد الدارمي ، عَن يحيى بْن مَعِين: ثقة.",3424],["علي بن المديني","وَقَال أَبُو الحسن بْن البراء، عن علي ابن المديني: هو عندي منكر.",3424],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة ثبت.",3424]],"4625":[["أبو بكر البزار","وَقَال أَبُو بَكْر البزار: أظن هَذَا خطأ من الناقل، يَعْنِي قَوْله من قال عَنْ عَبْدِ الْكَرِيمِ، عَنْ عَبد اللَّهِ بْن شقيق، عَن أَبِيهِ، قال: لان شقيقا والد عَبد اللَّهِ بْن شقيق جاهلي لا أعلم لَهُ إسلاما، وإنما هُوَ عَبْد الكريم بْن عَبد اللَّهِ بْن شقيق، عَن أَبِيهِ، قال: ولا نعلم رَوَى عَبد اللَّهِ بْن أَبي الحمساء إلا هَذَا الحَدِيث، وفيه اخْتِلاف غَيْر ذَلِكَ.",3186]],"4626":[["أحمد بن حنبل","قال عَبد اللَّهِ بن أحمد بْن حنبل عَن أبيه، وإسحاق بْن منصور عَن يحيى بْن مَعِين: ثقة.",3259]],"4628":[["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3573]],"4632":[["أبو حاتم الرازي","وَقَال إسحاق بْن منصور عَن يحيى بْن مَعِين، وأبو حاتم : ثقة.",3142],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة ثبت.",3142],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كَانَ ثقة، كثير الحديث، عالما، توفي سنة خمس وثلاثين، ويُقال: سنة ثلاثين ومئة، وهو ابن سبعين سنة، وليس له عقب .",3142]],"4634":[["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم : ثقة.",3160],["أبو حاتم الرازي","وَقَال أَبُو زُرْعَة ، وأَبُو حاتم : ثقة.",3160],["أبو حاتم الرازي","زاد أبو حاتم: صدوق .",3160]],"4638":[["محمد بن إسماعيل البخاري","وقَال البُخارِيُّ : يقال: إنه سمع من سلمان.",3226],["أبو حاتم الرازي","وَقَال أَبُو حاتم : روى عن سلمان مرسل، وعَن أَبِي الدرداء مرسل.",3226]],"4641":[["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3265]],"4644":[["علي بن المديني","قال البخاري ، عن علي ابن المديني: لَيْسَ بشيءٍ .",3289],["يحيى بن معين","وَقَال يَحْيَى بْن مَعِين: ثقة.",3289]],"4649":[["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3438]],"4653":[["أحمد بن حنبل","وَقَال أَبُو الْحَسَنِ الميموني، عن أَحْمَد بْن حنبل: ابْن أَبي نجيح ثقة، وكان أبوه من خيار عباد اللَّه .",3559],["الخطيب البغدادي","قال الحافظ أَبُو بَكْر الخطيب : حدث عَنْهُ عَمْرو بن شعيب وسفيان بْن عُيَيْنَة، وبين وفاتيهما ثمانون سنة . رَوَى لَهُ الْجَمَاعَة.",3559]],"4656":[["أبو حاتم الرازي","وَقَال أَبُو حاتم : صدوق.",3107],["أبو زرعة الدمشقي","وَقَال أَبُو زُرْعَة الدمشقي : سمعت الْوَلِيد بْن عتبة يَقُول: مَا بالعراق أقرأ من عَبد الله بْن أحمد بْن ذكوان. قال أَبُو زُرْعَة: وأنا أقول من عندي: لَمْ يكن بالعراق ولا بالحجاز ولا بالشام ولا بمصر ولا بخراسان فِي زمان عَبد اللَّهِ بْن ذكوان أقرأ عندي منه، والله أعلم.",3107]],"4657":[["الخطيب البغدادي","وَقَال أَبُو بَكْر الخطيب : كان ثقة ثبتا فهما.",3109]],"4658":[["أبو حاتم الرازي","قال أَبُو حَاتِم: صدوق .",3108]],"4665":[["أبو دواد السجستاني","قال أَبُو دَاوُد : شيخ منكر الحَدِيث.",3104],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ: حَدِيثه منكر.",3104]],"4667":[["يحيى بن معين","وَقَال عثمان بْن سَعِيد الدارمي : قُلْت ليحيى بْن مَعِين: ابْن إدريس أحب إليك أَوِ ابْن نمير؟ فَقَالَ: كلاهما ثقتان، إلا أَن ابْن إدريس أرفع، وهُوَ ثقة فِي كل شيء .",3111],["جعفر بن محمد الفريابي","وَقَال جعفر بْن مُحَمَّد الفريابي : وسألته، يعني مُحَمَّد بْن عَبد اللَّهِ بْن نمير، عَن عَبد اللَّهِ بْن إدريس وحفص، يَعْنِي ابن غياث - فَقَالَ: حفص أَكْثَر حَدِيثا، ولكن ابْن إدريس مَا خرج عَنْهُ فَإِنَّهُ فِيهِ أثبت وأتقن.",3111],["أبو حاتم الرازي","وَقَال أَبُو حاتم : هُوَ حجة يحتج بِهَا.",3111],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة ثبت.",3111],["محمد بن سعد كاتب الواقدي","زاد محمد بن سعد : فِي عشر ذي الحجة.",3111]],"4672":[["أبو حاتم الرازي","قال أبو حاتم : لا بأس به.",3106]],"4679":[["أبو زرعة الرازي","قال أَبُو زُرْعَة : صدوق.",3151],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة.",3151]],"4681":[["يحيى بن معين","قال عَبَّاس الدُّورِيُّ ، عَنْ يَحْيَى بْن مَعِين: ثبت .",3171],["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3171]],"4682":[["أبو زرعة الرازي","قال أَبُو زُرْعَة ، والنَّسَائي: ثقة.",3169],["أحمد بن شعيب النسائي","قال أَبُو زُرْعَة ، والنَّسَائي: ثقة.",3169],["أبو حاتم الرازي","وَقَال أَبُو حاتم : يكتب حديثه.",3169]],"4687":[["يعقوب بن شيبة","وَقَال يعقوب بْن شَيْبَة: ثقة.",3166]],"4689":[["مصعب بن عبد الله الزبيري","وَقَال أَبُو بَكْر بْن أَبي خيثمة ، عَن مصعب بْن عَبد اللَّهِ الزبيري: مَا رأيت أحدا من علمائنا يكرمون أحدا مَا يكرمون عَبد اللَّهِ بْن حسن بْن حسن.",3177]],"4690":[["يحيى بن معين","وَقَال أَبُو بَكْر بْن أَبي خيثمة : سألت يحيى بْن مَعِين، فَقُلْتُ: أَبُو حريز، من أين هو؟ بصري ثقة.",3179],["يحيى بن معين","وَقَال مُعَاوِيَة بْن صَالِح ، عَنْ يحيى بْن مَعِين: ضعيف .",3179],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : ثقة.",3179],["أبو حاتم الرازي","وَقَال أبو حاتم : حسن الحديث، لَيْسَ بمنكر الحَدِيث، يكتب حَدِيثه.",3179],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ضعيف.",3179]],"4691":[["أبو زرعة الرازي","قال أَبُو زُرْعَة : ضعيف.",3178]],"4698":[["أحمد بن حنبل","قال أَحْمَد بْن حَنْبَل: الحميدي عندنا إمام.",3222],["أبو حاتم الرازي","وَقَال أَبُو حاتم : أثبت النَّاس فِي ابْن عُيَيْنَة الحميدي، وهُوَ رئيس أَصْحَاب ابْن عُيَيْنَة، وهُوَ ثقة إمام.",3222],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سَعْد : عَبد اللَّهِ بْن الزُّبَيْر الأسدي الحميدي من بني أسد بن عبد العزى بْن قصي، صاحب ابْن عُيَيْنَة وراويته، مَاتَ بمكة سنة تسع عشرة ومئتين، وكَانَ ثقة، كثير الحَدِيث.",3222]],"4704":[["أحمد بن شعيب النسائي","وَقَال النَّسَائي: ثقة.",3239],["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سعد : كان ثقة، قليل الحَدِيث، توفي سنة ست وعشرين ومئة فِي خلافة الْوَلِيد بْن يَزِيد بن عَبد المَلِك .",3239]],"4709":[["أحمد بن شعيب النسائي","قال النَّسَائي: ثقة.",3290],["أبو حاتم الرازي","وَقَال أبو حاتم : يكتب حديثه.",3290]],"4710":[["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ثقة.",3291]],"4711":[["يحيى بن معين","وَقَال محمد بْن عوف الطائي ، عَنْ يحيى بْن مَعِين: ليس به بأس . وكَذَلِكَ قال النَّسَائي. وذكره محمد بْن سعد في الطبقة الخامسة من أهل الشام وَقَال : كان ثقة إن شاء الله.",3422],["عثمان بن سعيد الدارمي","وَقَال عثمان بن سَعِيد الدارمي : سألت عَبْد الرَّحْمَنِ بن إِبْرَاهِيمَ عَنْهُ، فوثقه جدا.",3422],["يعقوب بن سفيان","وَقَال يعقوب بْن سفيان : سألت عبد الرَّحْمَنِ بن إِبْرَاهِيمَ عَنْهُ فَقَالَ: كَانَ ثقة، وكان من أشراف البلد.",3422],["عمرو بن علي الفلاس","وَقَال عَمْرو بن علي : حديث الشاميين كله ضعيف إلا نفرا، منهم: عَبد اللَّهِ بْن العلاء بْن زبر.",3422],["أبو حاتم الرازي","وَقَال أبو حاتم: يكتب حديثه.",3422],["الدارقطني","وَقَال الدَّارَقُطْنِيُّ: ثقة، يجمع حديثه.",3422]],"4712":[["أحمد بن حنبل","قال حرب بْن إِسْمَاعِيل ، عَن أحمد بْن حنبل: لا بأس به.",3434]],"4716":[["نعيم بن حماد","وَقَال نعيم بْن حماد : قلت لعبد الرحمن بن مهدي: أيهما أفضل: عَبد اللَّهِ بْن الْمُبَارَك أَوْ سفيان الثوري؟ فَقَالَ: ابْن الْمُبَارَك. فقلت: إن الناس يخالفونك. فَقَالَ: إن الناس لم يجربوا، ما رأيت مثل ابْن الْمُبَارَك.",3470],["أحمد بن حنبل","وَقَال أَحْمَد بْن حَنْبَل : لم يكن فِي زمان ابْن الْمُبَارَك أطلب للعلم منه، رحل إِلَى اليمن وإلى مصر وإلى الشام. والبصرة، والكوفة. وكَانَ من رواة العلم وأهل ذاك، كتب عَنِ الصغار والكبار، وجمع أمرا عظيما ما كَانَ أحد أقل سقطا منه. كَانَ يحدث من كتاب، كَانَ رجلا صاحب حديث حافظا.",3470],["شعبة بن الحجاج","وَقَال مُحَمَّد بْن عَبد اللَّهِ بْن قهزاد، عن عبد العزيز بْن أَبي رزمة: قال لي شعبة من أين أنت؟ قال: قلت: من أهل مرو. قال: تعرف عَبد اللَّهِ بْن الْمُبَارَك؟ قال: قلت: نعم. قال: ما قدم علينا مثله.",3470],["سفيان بن عيينة","وَقَال عَمْرو بْن مُحَمَّد الناقد ، عن سفيان بن عُيَيْنَة: ما قدم علينا من أصحابنا أحد يشبه هذين الرجلين: عَبد اللَّهِ بْن الْمُبَارَك، ويحيى بْن زَكَرِيَّا بْن أَبي زائدة.",3470],["عبد الله بن المبارك","وَقَال المُسَيَّب بْن واضح : سمعت أبا إِسْحَاق الفزاري يَقُول: ابْن الْمُبَارَك إمام المسلمين.",3470],["محمد بن المثنى","وَقَال مُحَمَّد بْن المثنى : سمعت عَبْد الرحمن بْن مهدي يَقُولُ: ما رأت عيناي مثل أربعة: ما رأيت أحفظ للحديث من الثوري، ولا أشد تقشفا من شعبة، ولا اعقل من مالك بْن أنس، ولا انصح للأمة من عَبد اللَّهِ بْن الْمُبَارَك.",3470],["يحيى بن معين","وَقَال إِبْرَاهِيم بْن عَبد اللَّهِ بْن الجنيد ، عَنْ يحيي بن مَعِين: كَانَ عَبد اللَّهِ بن المبارك كيسا مستثبتا ثقة، وكَانَ عالما صحيح الْحَدِيث، وكانت كتبه التي حدث بها عشرين ألفا، أَوْ واحدا وعشرين ألفا .",3470],["الخطيب البغدادي","قال الْحَافِظُ أَبُو بكر الخطيب : حدث عنه مَعْمَر بْن راشِد، والحسين بْن داود البلخي، وبين وفاتيهما مئة وثنتان وثلاثون سنة. وقِيلَ: مئة وثلاثون سنة، وقيل: مئة وتسع وعشرون سنة . روى له الجماعة",3470]],"4717":[["أبو زرعة الرازي","وَقَال إسحاق بْن منصور عَن يَحْيَى بْن مَعِين، وأبو زُرْعَة : ثقة .",3471]],"4718":[["يحيى بن معين","قال إِسْحَاق بْن منصور ، عَنْ يحيى بْن مَعِين: ثقة.",3504],["أبو حاتم الرازي","وَقَال أبو حاتم : لا بأس بِهِ.",3504]],"4728":[["أحمد بن شعيب النسائي","قال النَّسَائي : لا بأس بِهِ .",3578],["الخطيب البغدادي","وَقَال أَبُو بَكْر الخطيب : كان ثقة.",3578]],"4730":[["يحيى بن معين","وَقَال إسحاق بْن منصور ، عَن يحيى بْن مَعِين: ثقة .",3584]],"4732":[["أحمد بن حنبل","قال حرب بْن إِسْمَاعِيلَ : قلت لأحمد بْن حَنْبَل: عَبد اللَّهِ بْن الوليد العدني، كيف حديثه؟ قال: سمع من سفيان - وجعل يصحح سماعه - ولكن لم يكن صاحب حديث، وحديثه حديث صحيح، وكَانَ ربما أخطأ فِي الأَسماء، وقد كتبت عنه أنا كثيرا.",3586],["أبو زرعة الرازي","وَقَال أَبُو زُرْعَة : صدوق.",3586],["أبو حاتم الرازي","وَقَال أبو حاتم : يكتب حديثه، ولا يحتج بِهِ.",3586]],"4741":[["أبو عيسى الترمذي","وَقَال التِّرْمِذِيّ : ضعيف، ضعفه يَحْيَى بْن سَعِيد وغيره.",3133],["أحمد بن شعيب النسائي","وَقَال النَّسَائي : ليس بثقة.",3133],["أبو حاتم الرازي","وَقَال أَبُو حاتم والدارقطني : ضعيف الحَدِيث.",3133],["الدارقطني","وَقَال أَبُو حاتم والدارقطني : ضعيف الحَدِيث.",3133]],"4745":[["أبو زرعة الرازي","وَقَال أبو زُرْعَة : لا بأس به.",3134]],"4746":[["محمد بن سعد كاتب الواقدي","وَقَال مُحَمَّد بْن سَعْد : السهمي بطن من باهلة، وكان ثقة صدوقا، نزل بغداد عَلَى سَعِيد بْن سلم الْبَاهِلِي، وسمع منه البغداديون، ولَمْ يزل بِهَا حَتَّى مَاتَ فِي خلافة الْمَأْمُون ليلة الثلاثاء لثلاث عشرة ليلة بقيت من المحرم سنة ثمان ومئتين .",3137]]});